/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"운송의 효용과 기능","줄":[{"t":"장소적 효용: 운송은 공간적 거리의 격차를 해소한다. 생산된 장소와 소비되는 장소의 불일치를 조정한다","src":"기출 2021-1, 2025-8"},{"t":"시간적 효용: 운송은 수송 중 물품을 일시적으로 보관한다","src":"기출 2021-1, 2022-2, 2025-8, 2026-6"},{"t":"운송은 재화의 생산과 소비에 따른 파생적 수요다. 운송서비스 수요는 상품 수요에 따라 결정된다","src":"기출 2021-1, 2025-8, 2026-6"},{"t":"운송은 생산과 동시에 소비되는 즉시재다","src":"기출 2023-3"},{"t":"운송공급은 비교적 계획적이고 체계적이다. 운송수요는 상대적으로 무계획적이고 비체계적이다","src":"기출 2023-3"},{"t":"개별 운송수요는 다양하지만 모아서 보면 집합성을 가진다","src":"기출 2023-3"},{"t":"운송수단 간 대체성이 높아 운송수요에 탄력적으로 대응할 수 있다","src":"기출 2023-3"},{"t":"운송은 재화를 효용가치가 낮은 장소에서 높은 장소로 이전하는 활동을 포함한다","src":"기출 2023-6"},{"t":"운송 기능: 한계생산비 차이를 극복하는 장소적 조절, 원재료 이동을 통한 생산비 절감, 운송 효율화를 통한 물류비 절감, 지역 간 경쟁력 있는 상품의 생산·교환·소비 촉진","src":"기출 2023-5"},{"t":"운송 효율화는 생산지와 소비지를 확대시켜 시장을 활성화한다. 지역 간 상품 가격의 차이를 줄인다","src":"기출 2022-2, 2025-8"},{"t":"운송은 지역과 거리를 극복해 생산과 판매를 촉진한다","src":"기출 2026-6"},{"t":"운송영역의 범위에 따라 국내운송과 국제운송으로 구분한다","src":"기출 2025-8"},{"t":"오늘날 운송은 공간적 거리 극복뿐 아니라 토탈 마케팅 비용 절감과 고객서비스 향상까지 강조한다. 본원적 활동인 운송에 부가가치 활동이 추가되어 오늘날의 물류로 발전했다","src":"기출 2023-6"},{"t":"경제적 운송의 기본 원칙: 규모의 경제 원칙, 거리의 경제 원칙","src":"기출 2021-1"},{"t":"규모의 경제: 한 번에 많이 실어 나를수록 단위당 운송비가 내려간다. 거리의 경제: 운송거리가 길수록 km당 운송비가 내려간다","src":"보충"}]},{"머리":"물류 정의","줄":[{"t":"미국 마케팅협회: 물류는 생산지에서 소비지에 이르는 상품의 이동과 취급에 관한 관리","src":"기출 2023-6"},{"t":"1976년 미국물류관리협회: 물류는 수요예측과 주문처리까지 포함한다. 이를 마케팅 영역으로 구분하지 않는다","src":"기출 2023-6, 보충"}]},{"머리":"운송의 3요소","줄":[{"t":"Mode(운송수단): 화물자동차, 화물열차, 선박, 항공기 등 운송을 직접 담당하는 수단. 복합운송에서 역할이 중요하다","src":"기출 2022-1, 2024-5, 2025-6"},{"t":"Node(운송점·거점): 물류센터, 제조공장, 화물터미널, 항만, 공항, 철도역, 배송센터 등 화물의 집하·환적·중계가 일어나는 장소나 시설","src":"기출 2022-1, 2024-5, 2025-6, 2026-2"},{"t":"Link(운송경로·통로): 공로, 철도, 해상항로, 항공로 등 운송수단이 다니는 통로. 각 운송점을 연결하는 구간 또는 경로","src":"기출 2021-1, 2022-1, 2024-5, 2025-6"},{"t":"3요소 암기용 구분: 수단은 Mode, 점은 Node, 선은 Link. Load와 Rate는 3요소가 아니다","src":"기출 2022-1"}]},{"머리":"운송 형태 구분","줄":[{"t":"정형운송: 파렛트·컨테이너 같은 단위적재용기에 화물을 적재해 운송","src":"기출 2026-4"},{"t":"비정형운송: 단위화할 수 없는 화물을 특수한 시설과 구조를 갖춘 운송수단으로 운송","src":"기출 2026-4"},{"t":"정기운송: 물동량에 상관없이 정해진 일정에 맞춰 운송","src":"기출 2026-4"},{"t":"비정기운송: 화주의 필요에 따라 그때그때 운송. 운송인이 원하는 시간에 맞추는 형태가 아니다","src":"보충"},{"t":"복합운송: 두 가지 이상의 운송수단을 이용해 운송","src":"기출 2026-4"}]},{"머리":"운송시장 변화와 국내 운송 특징","줄":[{"t":"최근 운송시장 변화: 환경규제 강화, 물류보안 중요성 증대, 정보시스템 활용 증가, 구매고객 서비스 수준 향상. 화물은 소품종 대형화가 아니라 다품종 소량화 쪽으로 간다","src":"기출 2021-7, 보충"},{"t":"철도르네상스: 시간적 제약을 극복하고 도심 접근성이 좋아 항공운송의 대체수단으로 떠오른다","src":"기출 2023-2"},{"t":"운송수단의 대형화·신속화로 거점(Hub) 간 경쟁이 심해지고 거점 수는 줄며 기능은 복합화된다","src":"기출 2023-2"},{"t":"기후변화 대응으로 운송수단의 친환경 기술혁신이 조선업 부흥을 이끈다","src":"기출 2023-2"},{"t":"미중 갈등에 따른 공급망 재편: 최저 생산비보다 안정적인 공급망을 중시하며 협업적 관계를 강조","src":"기출 2023-2"},{"t":"국내 화물운송에서 공로운송의 비중이 크다. 철도는 도로운송보다 수송분담률이 낮다","src":"기출 2021-21, 2025-11, 2023-7"},{"t":"화물운송의 출발·도착 경로의 편중도가 높다. 수출입 물동량은 항만 이용 비중이 가장 크고 특정 항만 편중도도 높다","src":"기출 2023-7"},{"t":"화물자동차운송사업은 영세업체가 많고 전문화·대형화가 미흡해 서비스 질이 위협받는다","src":"기출 2023-7"},{"t":"화주기업과 운송인의 협업이 미흡해 제3자물류·제4자물류로 가기 위한 정책 지원 확대가 필요하다","src":"기출 2023-7"}]},{"머리":"3S1L 원칙","줄":[{"t":"Speedy(신속), Safely(안전), Surely(정확), Low(저비용). 대체성은 3S1L에 들어가지 않는다","src":"기출 2023-8"}]},{"머리":"운송 합리화 방안(해야 하는 것)","줄":[{"t":"수송체계 다변화, 일관파렛트화(Palletization) 지원, 차량운행 경로 최적화, 물류정보시스템 정비","src":"기출 2022-7"},{"t":"과학적 관리에 입각한 계획수송체계 강화, 운송수단의 대형화·신속화·표준화, 공동수배송 체계 활성화, 운송업체의 대형화·전문화","src":"기출 2023-4"},{"t":"컨테이너·파렛트를 이용한 운송 확대, 교통정보시스템과 화물추적시스템 연계, 철도·연안운송 연계로 화물운송시스템 구축, 공동수배송 체계 구축","src":"기출 2025-3"},{"t":"운송수단 및 화물의 표준화, 적재율 향상, 물류정보시스템 활용","src":"기출 2026-18"},{"t":"적재율 증대와 비용 절감을 위해 자가용보다 영업용 화물차량 사용을 늘린다","src":"보충"}]},{"머리":"운임탄력성","줄":[{"t":"운송수요 탄력성 = (수요 변화량 ÷ 수요 수준) ÷ (운임 변화량 ÷ 운임 수준). 분자는 수요 쪽, 분모는 운임 쪽","src":"기출 2025-7, 2026-32"},{"t":"계산 순서: 수요 변화율 구하기, 운임 변화율 구하기, 앞을 뒤로 나누기. 예: 수요 5/10, 운임 1/4이면 0.5 ÷ 0.25 = 2","src":"기출 2025-7"},{"t":"대체 운송수단이 다양하면 운임탄력성이 크다","src":"기출 2025-5"},{"t":"대체되는 화물이 다양하면 해당 화물 운송수요는 운임에 탄력적이다","src":"기출 2025-5"},{"t":"판매단가가 높은 상품은 운임부담력이 높아 운임이 올라도 운송수요가 크게 줄지 않는다","src":"기출 2025-5"},{"t":"운임탄력성은 운임 외에 운송 원가에도 영향을 받는다","src":"기출 2025-5"},{"t":"상품가격 대비 운임 비중이 클수록 운임 상승이 상품수요를 줄여 운송수요 탄력성이 커진다","src":"기출 2023-3"},{"t":"탄력성이 낮으면 운임이 변해도 수요 변화가 작다","src":"기출 2025-5, 보충"}]}],"함정":[{"x":"운송의 3요소(Mode, Node, Link) 중 Mode는 각 운송점을 연결하여 운송되는 구간 또는 경로를 의미한다.","o":"운송점을 연결하는 구간·경로는 Link. Mode는 운송수단.","src":"기출 2021-1"},{"x":"운송 효율화 측면에서 운송비용을 절감하기 위해 다빈도 소량운송을 실시한다.","o":"다빈도 소량운송은 적재율을 떨어뜨려 비용을 올린다. 비용 절감은 적재율 향상·공동수배송·대형화로 한다.","src":"기출 2022-2, 2026-6, 보충"},{"x":"개별적 운송수요는 다양하므로 운송수요는 집합성을 가질 수 없다.","o":"개별 수요가 다양해도 운송수요는 집합성을 가진다.","src":"기출 2023-3"},{"x":"보관과 배송을 연결하는 인적 조절기능이 있다.","o":"출제 오답(바른 수치 미확인). 운송의 조절 기능은 장소적 조절이다.","src":"기출 2023-5"},{"x":"1976년 미국물류관리협회는 물류를 생산에서 소비에 이르는 여러 활동을 포함하되 수요예측이나 주문처리는 물류가 아닌 마케팅의 영역으로 구분하였다.","o":"1976년 미국물류관리협회는 수요예측·주문처리까지 물류 활동에 포함했다.","src":"기출 2023-6, 보충"},{"x":"공로운송은 운송거리가 단거리이기 때문에 전체 운송에서 차지하는 비중이 낮다.","o":"공로운송은 국내 화물운송에서 비중이 크고 철도보다 수송분담률이 높다.","src":"기출 2023-7, 2021-21"},{"x":"적재율 증대와 비용감소를 위해 영업용 보다는 자가용 화물차량을 사용한다.","o":"자가용보다 영업용 화물차량 사용을 늘린다.","src":"기출 2025-3, 보충"},{"x":"운임탄력성이 낮은 경우 운임이 변화하면 운송수요가 크게 변화한다.","o":"탄력성이 낮으면 운임이 변해도 수요 변화가 작다.","src":"기출 2025-5"},{"x":"Mode라고 하며 복합운송의 역할이 중요시되고 있다. (공로·철도·해상항로·항공로 같은 통로 설명 문항의 오답)","o":"통로는 Link다. Mode는 자동차·열차·선박·항공기 같은 운송수단.","src":"기출 2025-6"},{"x":"철도역, 배송센터, 물류터미널 등이 이에 해당된다. (통로 설명 문항의 오답)","o":"철도역·배송센터·물류터미널은 Node.","src":"기출 2025-6"},{"x":"운송을 직접 담당하는 수단으로 자동차, 선박, 항공기, 철도 차량 등이 있다. (통로 설명 문항의 오답)","o":"운송수단은 Mode.","src":"기출 2025-6"},{"x":"운송을 위한 상품을 처리 및 보관하는 장소 또는 시설을 의미한다. (통로 설명 문항의 오답)","o":"처리·보관 장소나 시설은 Node.","src":"기출 2025-6"},{"x":"운송서비스 수요는 상품 수요와 독립적으로 결정되는 특성이 있다.","o":"운송수요는 상품 수요에 따라 생기는 파생적 수요.","src":"기출 2025-8"},{"x":"도로, 철도, 항로 등과 같은 화물의 통행로를 의미한다. (Node 설명 문항의 오답)","o":"통행로는 Link.","src":"기출 2026-2"},{"x":"운송을 직접 수행하는 차량, 열차, 선박, 항공기 등을 의미한다. (Node 설명 문항의 오답)","o":"운송수단은 Mode.","src":"기출 2026-2"},{"x":"운송행위를 담당하는 주체들과 이들이 운송 서비스를 제공하는 프로세스를 의미한다. (Node 설명 문항의 오답)","o":"출제 오답(바른 수치 미확인). Node는 집하·환적·중계 장소나 시설.","src":"기출 2026-2"},{"x":"운송수요에 대해 운송공급이 제공되는 운송시장을 의미한다. (Node 설명 문항의 오답)","o":"출제 오답(바른 수치 미확인). Node는 집하·환적·중계 장소나 시설.","src":"기출 2026-2"},{"x":"비정기운송은 운송인이 원하는 시간에 맞추어 운송하는 형태이다.","o":"비정기운송은 화주의 필요에 따라 그때그때 운송하는 형태(보충). 정해진 일정에 맞추는 것은 정기운송.","src":"기출 2026-4, 보충"},{"x":"운송비용을 절감하기 위하여 다빈도 소량 운송을 실시한다.","o":"다빈도 소량운송은 비용을 올린다.","src":"기출 2026-6"},{"x":"운송화물의 소품종 대형화 (최근 운송시장 변화 문항의 오답 선지)","o":"변화 방향은 다품종 소량화.","src":"기출 2021-7, 보충"},{"x":"운송업체의 일반화 및 소형화 유도 (합리화 방안 문항의 오답 선지)","o":"운송업체는 대형화·전문화.","src":"기출 2022-7, 2023-4"},{"x":"적재율 감소를 통한 물류합리화 / 적재율 감소 및 차량의 배송 빈도 증가 (합리화 문항의 오답 선지)","o":"적재율은 높인다.","src":"기출 2021-19, 2023-4"},{"x":"운송수단의 소형화 및 일반화 (합리화 문항의 오답 선지)","o":"운송수단은 대형화·신속화·표준화.","src":"기출 2026-18"},{"x":"3S1L의 기본원칙 중 대체성","o":"3S1L은 신속·안전·정확·저비용.","src":"기출 2023-8"}]},"#2":{"묶음":[{"머리":"운송수단 선택 시 고려 요건","줄":[{"t":"경제성: 운송비가 얼마나 드는가","src":"기출 2022-6, 2024-3, 보충"},{"t":"신속성: 운송 소요시간이 얼마나 짧은가","src":"기출 2022-6, 2024-3, 보충"},{"t":"확실성: 지정기일 내 인도가 가능한가, 정시운행이 가능한가","src":"기출 2024-3"},{"t":"편리성: 물류네트워크 연계점에서 연결이 쉬운가, 운송절차와 송장서류 작성이 간단한가, 필요시 운송서류를 이용할 수 있는가","src":"기출 2022-6"},{"t":"안전성: 화물의 손상·사고 위험이 적은가","src":"기출 2022-6, 보충"},{"t":"운송수단 선택 시 화물유통 제반여건을 확인하고 운송수단별 평가항목을 검토한다. 운송수단 특성에 따라 최적경로와 배송빈도를 고려해 운송계획을 세운다","src":"기출 2022-3"},{"t":"물류흐름을 최적화해 물류비를 줄이고 고객만족을 높이는 전략을 쓴다. 운송비 부담력도 고려한다. 틈새시장 공략처럼 특화된 서비스에는 일반 기준과 다른 기준을 쓸 수 있다","src":"기출 2022-3"},{"t":"수송비와 보관비는 상관관계가 있으므로 총비용 관점에서 운송수단을 선택한다","src":"기출 2022-4"},{"t":"운송수단별 운송물량에 따라 운송비용에 차이가 있어 비교우위가 다르다","src":"기출 2022-4"},{"t":"철도운송은 운송기간 중 재고유지로 재고유지비용이 늘 수 있다. 항공운송은 운송 소요시간이 짧아 재고유지비용이 줄어든다","src":"기출 2022-4"}]},{"머리":"화물자동차(공로) 운송","줄":[{"t":"기동성과 신속한 전달로 문전운송(door-to-door)이 가능하다. 다른 운송수단과 연계하지 않고도 일관운송 서비스를 제공한다. 운송을 완성시켜주는 역할","src":"기출 2021-14, 2024-39, 2026-3"},{"t":"필요시 즉시 배차가 가능하다. 차량 관리와 신속한 배차가 어렵지 않다","src":"기출 2024-1, 2026-3"},{"t":"운송단위가 작아 장거리 대량화물 운송에는 맞지 않는다. 장거리·대량화물은 철도·해상이 유리하다","src":"기출 2024-39, 2022-8, 2026-3"},{"t":"근거리·소량화물은 화물자동차가 경제적이다","src":"기출 2022-8, 2025-9, 2026-5"},{"t":"철도에 비해 연료비 등 에너지 소비가 많아 에너지 효율이 낮다. 해상운송보다 화물의 중량·부피 제한이 크다","src":"기출 2021-14, 2024-39, 보충"},{"t":"철도에 비해 정시성이 낮고 사고율이 높으며 안전도가 낮다. 화물 중량에는 제한이 있다","src":"기출 2021-14, 2024-39, 2026-3"},{"t":"공로운송은 접근성이 가장 뛰어나다. 1회 수송량이 적어 고가·소량 화물을 주로 맡고 운임부담력은 상대적으로 높다","src":"기출 2023-1, 보충"},{"t":"기후 영향을 받지 않는 전천후 운송에는 도로보다 철도가 적합하다","src":"기출 2026-5"}]},{"머리":"영업용 화물차(용차) 이용의 장점","줄":[{"t":"귀로 시 복화화물 운송이 가능해 운송비가 저렴하다","src":"기출 2023-13, 2026-19"},{"t":"돌발적·불규칙 운송수요 증가에 탄력적으로 대응할 수 있다","src":"기출 2023-13, 2026-19"},{"t":"필요한 시점에 필요한 수량·규격·종류의 차량을 이용할 수 있다","src":"기출 2023-13, 2026-19"},{"t":"운임이 저렴하고 서비스 수준이 높은 업체와 계약운송이 가능하다","src":"기출 2023-13, 2026-19"},{"t":"자가용 화물차보다 기동성이 높다고 단정하거나 보험료가 적다고 보지 않는다","src":"기출 2023-13"}]},{"머리":"철도운송","줄":[{"t":"장거리·대량화물에 유리하다. 단거리에서는 자동차가 유리하다","src":"기출 2022-8, 2024-1, 2025-9"},{"t":"안전도가 높고 친환경적이다. 전국 네트워크가 있다. 계획적인 운송이 가능하다","src":"기출 2022-19, 2026-3"},{"t":"기후와 교통체증의 영향이 적고 계획적으로 운행할 수 있다","src":"기출 2021-21, 2024-17, 2025-11"},{"t":"초기 구축비용 등 고정비용이 많이 든다. 초기인프라 진입비용이 낮지 않다","src":"기출 2023-1, 2024-17"},{"t":"km당 운임은 단거리일수록 비싸고 장거리일수록 싸다(원거리 체감)","src":"기출 2024-17"},{"t":"타 운송수단과의 연계 없이는 Door to Door가 안 된다","src":"기출 2022-19"},{"t":"화차의 소재관리가 불편해 열차편성이 느리다. 공로운송보다 먼저 대량화물을 운송했다","src":"기출 2024-17"}]},{"머리":"해상·연안운송","줄":[{"t":"대량화물 장거리에 적합하다. 낮은 운임부담력(저가 대량화물)으로 국제물류의 중심 역할을 한다","src":"기출 2023-21, 2023-1"},{"t":"해상화물은 화물의 크기·무게의 영향을 적게 받아 대용량 화물에 유리하다","src":"기출 2025-9"},{"t":"대량화물을 운송할 때 단위비용이 낮아져 자동차 운송보다 유리하다","src":"기출 2022-4"},{"t":"기후 영향을 많이 받는다. 파손·분실·사고 위험이 크고 타 운송수단보다 안전성이 낮다","src":"기출 2024-1, 2023-21"},{"t":"해상운송은 떠다니는 영토로 불릴 만큼 국제성이 높다. 제2선적 같은 전략적 지원이 강조된다. 관련 산업 발전, 지역경제 활성화, 국제수지 개선에 기여한다","src":"기출 2023-21"},{"t":"선박 대형화로 기존 운하경로에 제약이 생겨 북극항로 같은 대체경로 개발이 활발하다","src":"기출 2023-21"},{"t":"연안운송: 철도·도로 운송의 대체수단으로 국내 항만을 오가는 운송. 도서지역 생필품 안정 공급, 도로 혼잡 경감, 친환경","src":"기출 2025-32"},{"t":"연안운송은 대량·중장거리 위주라 소량 다빈도 문전수송에는 맞지 않는다","src":"기출 2025-32"},{"t":"대량화물의 장거리 운송은 도로보다 해상이 적합하다","src":"기출 2026-5"}]},{"머리":"항공운송","줄":[{"t":"장거리를 신속하게 운송한다. 항공기 대형화로 운송비 절감 효과가 있다","src":"기출 2023-1"},{"t":"중량·용적에 제한이 있다. 장거리 대용량·고중량 화물에는 맞지 않는다","src":"기출 2024-1, 2025-9"},{"t":"중량과 부피가 작고 장거리·고가인 화물은 해상보다 항공이 적합하다","src":"기출 2026-5"},{"t":"장기 운송 시 가치가 떨어지는 신선화물은 해상이 아니라 항공이 적합하다","src":"기출 2026-5"}]},{"머리":"파이프라인 운송","줄":[{"t":"초기 시설 설치비가 많이 들지만 유지비는 저렴하다","src":"기출 2022-5, 2025-9, 2026-1"},{"t":"유류·가스를 연속적·대량으로 운송한다","src":"기출 2022-5, 2024-1, 2026-1"},{"t":"환경오염이 적은 친환경 운송이다. 컴퓨터시스템으로 운영 자동화가 가능하다","src":"기출 2022-5, 2026-1"},{"t":"운송 대상(제품)과 운송경로에 대한 제약이 크다","src":"기출 2022-5, 2026-1"}]}],"함정":[{"x":"타 운송수단과 연동하지 않고는 일관된 서비스를 제공할 수 없다. (화물자동차 설명 문항의 오답)","o":"화물자동차는 다른 수단과 연계하지 않고도 일관(문전) 서비스가 가능하다.","src":"기출 2021-14"},{"x":"철도운송에 비해 연료비 등 에너지 소비가 적어 에너지 효율성이 높다.","o":"공로운송은 철도보다 에너지 소비가 크다.","src":"기출 2021-14, 보충"},{"x":"해상운송에 비해 화물의 중량이나 부피에 대한 제한이 적어 대량화물의 운송에 적합하다.","o":"공로운송은 해상보다 중량·부피 제한이 크다.","src":"기출 2021-14, 보충"},{"x":"철도운송에 비해 정시성이 높다.","o":"공로운송은 철도보다 정시성이 낮다.","src":"기출 2021-14, 2024-39"},{"x":"운송수단의 선택에서 특화된 운송서비스나 틈새시장 공략의 경우에도 일반적인 선택기준만 적용하고 다른 기준을 적용하는 경우는 없다.","o":"틈새시장 등에는 다른 기준을 적용할 수 있다.","src":"기출 2022-3"},{"x":"운송비 부담력은 고려하지 않는다.","o":"운송비 부담력도 고려한다.","src":"기출 2022-3"},{"x":"해상운송은 장거리 운송의 장점을 가지고 있지만, 대량화물을 운송할 때 단위비용이 낮아져 자동차 운송보다 불리하다.","o":"단위비용이 낮아져 자동차 운송보다 유리하다.","src":"기출 2022-4"},{"x":"운송대상과 운송경로에 관한 제약이 적다. (파이프라인)","o":"파이프라인은 운송 대상과 경로 제약이 크다.","src":"기출 2022-5, 2026-1"},{"x":"철도운송은 장거리, 대량운송에 유리하지만 운송시간이 오래 걸리고 초기인프라 설치관련 진입비용이 낮다.","o":"철도는 초기 인프라 진입비용이 높다.","src":"기출 2023-1"},{"x":"해상운송은 대량화물의 장거리운송에 적합하지만 정기항로에 치우쳐 유연성과 전문성이 떨어진다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-1"},{"x":"공로운송은 접근성이 가장 뛰어나지만 1회 수송량이 적어 운임부담력이 상대적으로 낮다.","o":"공로운송은 운임부담력이 상대적으로 높다(보충).","src":"기출 2023-1, 보충"},{"x":"연안운송은 초기 항만하역시설투자비가 적은 편이고 해상경로가 비교적 짧은 단거리 수송에 유리하다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-1"},{"x":"해상운송은 물품의 파손, 분실, 사고발생의 위험이 적고, 타 운송수단에 비해 안전성이 높다.","o":"해상운송은 파손·분실·사고 위험이 크다.","src":"기출 2023-21, 보충"},{"x":"자가용 화물차 이용 시보다 기동성이 높고, 보험료가 적다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-13"},{"x":"화물자동차에 비해 철도는 단거리 운송에 유리하다.","o":"철도는 장거리·대량에 유리하다.","src":"기출 2024-1"},{"x":"운송단위가 작아서 장거리 대량화물 운송에 적합하다. (공로)","o":"운송단위가 작아 장거리 대량운송에는 맞지 않는다.","src":"기출 2024-39"},{"x":"철도운송에 비해 사고율이 낮고 안전도가 높다. (공로)","o":"공로는 철도보다 안전도가 낮다.","src":"기출 2024-39"},{"x":"운송화물의 중량에 제한이 없다. (공로)","o":"공로운송은 중량 제한이 있다.","src":"기출 2024-39, 2026-3"},{"x":"항공운송은 장거리 및 대용량ㆍ고중량 운송에 유리하다.","o":"항공은 중량·용적 제한이 있어 소형·경량·고가 화물에 유리하다.","src":"기출 2025-9"},{"x":"이용제품과 운송경로에 관한 제한이 적다. (파이프라인)","o":"제한이 크다.","src":"기출 2026-1"},{"x":"장거리 대량화물의 운송에 유리하다. (공로 문항의 오답)","o":"장거리 대량화물은 철도·해상.","src":"기출 2026-3"},{"x":"안전도가 높고 친환경적인 운송 수단이다. (공로 문항의 오답)","o":"안전도·친환경은 철도의 특징.","src":"기출 2026-3"},{"x":"차량의 관리와 신속한 배차가 어렵다. (공로 문항의 오답)","o":"공로는 신속한 배차가 쉽다.","src":"기출 2026-3"},{"x":"장기 운송시 가치가 하락하는 신선화물의 경우에는 항공운송보다 해상운송이 적합하다.","o":"신선화물은 항공이 적합.","src":"기출 2026-5"},{"x":"근거리 운송 및 소량화물인 경우에는 도로운송보다 철도운송이 적합하다.","o":"근거리·소량은 도로.","src":"기출 2026-5"},{"x":"기후에 영향을 받지 않는 전천후 운송의 경우에는 철도운송보다 도로운송이 적합하다.","o":"전천후 운송은 철도가 적합.","src":"기출 2026-5"},{"x":"대량화물의 장거리 운송인 경우에는 해상운송보다 도로운송이 적합하다.","o":"대량 장거리는 해상이 적합.","src":"기출 2026-5"},{"x":"물류시스템의 표준화 및 일관화를 구축한다. (영업용 화물차 장점 문항의 오답)","o":"출제 오답(바른 수치 미확인). 영업용 장점은 탄력 대응·복화·차종 선택·계약운송.","src":"기출 2026-19"},{"x":"운송 중량에 대한 제한이 없다.","o":"공로운송은 운송 중량에 제한이 있다.","src":"기출 2026-3"}]},"#3":{"묶음":[{"머리":"화물자동차의 범위(법령)","줄":[{"t":"화물자동차: 일반형·덤프형·밴형 및 특수용도형 화물자동차와, 견인형·구난형 및 특수용도형 특수자동차","src":"화물자동차 운수사업법 시행규칙 제3조 제1항"},{"t":"밴형 화물자동차 요건: 물품적재장치의 바닥면적이 승차장치의 바닥면적보다 넓을 것, 승차 정원이 3명 이하일 것(호송경비 차량 등 예외 있음)","src":"화물자동차 운수사업법 시행규칙 제3조 제1항"},{"t":"밴형 화물자동차: 일반 화물자동차의 적재공간에 박스형 덮개를 고정적으로 설치한 차량. 지붕구조의 덮개가 있는 화물자동차는 밴형","src":"기출 2023-15, 2025-2"},{"t":"리치스태커, 스트래들 캐리어, 하이로더, 포크리프트는 하역·운반 장비이며 밴형 화물자동차가 아니다","src":"기출 2023-15, 2025-2"}]},{"머리":"구조에 의한 분류: 전용특장차와 합리화특장차","줄":[{"t":"전용특장차: 자체 동력으로 장착된 기계장치를 직접 가동시켜 화물을 하역·운반한다","src":"기출 2024-31"},{"t":"전용특장차의 종류: 덤프트럭, 믹서트럭(믹서차량), 분립체 운송차, 액체 운송차(탱크로리), 냉동차","src":"기출 2022-10, 2025-10, 2026-11, 2023-11"},{"t":"덤프트럭: 적재함 높이를 경사지게 해 적재물을 하역한다","src":"기출 2024-31"},{"t":"믹서트럭: 콘크리트를 섞으면서 건설현장 등으로 운송한다","src":"기출 2024-31"},{"t":"분립체 운송차: 시멘트·곡물 등 분립체를 자루에 담지 않고 운반하도록 설계된 차량","src":"기출 2024-31"},{"t":"액체 운송차(탱크로리): 액체 화물 운송 전용","src":"기출 2025-10"},{"t":"합리화특장차: 적재·하역 작업의 합리화를 위해 특수기기를 장착한 차량","src":"기출 2024-31"},{"t":"합리화특장차의 종류: 리프트게이트 부착차량, 측면 전개차(윙바디 계열), 시스템 차량, 적화·하역 합리화차","src":"기출 2022-10, 2023-11, 2025-10, 2026-11"},{"t":"구분 요령: 믹서·분립체·액체·냉동·덤프는 전용특장차. 리프트게이트·측면 전개·시스템 차량은 합리화특장차","src":"기출 2022-10, 2023-11, 2025-10, 2026-11"}]},{"머리":"트레일러 트럭의 종류","줄":[{"t":"풀(Full) 트레일러: 트랙터와 트레일러가 완전히 분리되어 있고 트랙터 자체도 바디(Body)를 가진다","src":"기출 2024-38"},{"t":"세미(Semi) 트레일러: 트랙터와 트레일러가 적재하중을 분담한다. 트레일러 일부 하중을 트랙터가 부담한다","src":"기출 2024-38, 2022-12"},{"t":"폴(Pole) 트레일러: 트랙터에 턴테이블을 설치하고 트레일러를 연결한 뒤 대형파이프·H형강·교각·대형목재 같은 장척물 수송에 쓴다","src":"기출 2022-12, 2024-38"},{"t":"폴 트레일러는 컨테이너 운송용이 아니다. 컨테이너 운송용은 스켈레탈 트레일러(컨테이너를 싣는 골격형)","src":"기출 2026-16, 2021-31, 보충"},{"t":"저상식 트레일러: 평상식보다 낮은 화물대","src":"기출 2026-16"},{"t":"중저상식 트레일러: 화물대 중간 부분이 낮다","src":"기출 2026-16"},{"t":"오픈탑 트레일러: 천장이 개구된 형태. 석탄·철광석 등에 포장(덮개)을 덮어 운송","src":"기출 2021-31, 2026-16"},{"t":"밴 트레일러: 일반잡화 및 냉동화물 운송","src":"기출 2026-16"},{"t":"평상식 트레일러, 스켈레탈 트레일러, 오픈탑·저상식·중저상식은 문항에서 서로 구별해 묻는다","src":"기출 2021-31"}]}],"함정":[{"x":"트렉터와 트레일러가 완전히 분리되어 있고, 트레일러 자체도 바디를 가지고 있으며 중소형이다. (폴 트레일러 설명 문항의 오답)","o":"완전 분리형은 풀 트레일러이고 바디를 가지는 쪽은 트랙터다.","src":"기출 2022-12, 2024-38"},{"x":"트레일러의 일부 하중을 트렉터가 부담하는 것으로 측면에 미닫이문이 부착되어 있다. (폴 트레일러 설명 문항의 오답)","o":"일부 하중을 트랙터가 부담하는 것은 세미 트레일러. 폴 트레일러는 장척물용.","src":"기출 2022-12"},{"x":"컨테이너 트렉터는 트레일러 2량을 연결하여 사용한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2022-12"},{"x":"대형 중량화물을 운송하기 위하여 여러 대의 자동차를 연결하여 사용한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2022-12"},{"x":"액체운송차는 콘크리트를 섞으면서 건설현장 등으로 운송하는 차량이다.","o":"콘크리트를 섞으면서 운송하는 차량은 믹서트럭.","src":"기출 2024-31"},{"x":"폴 트레일러는 주로 컨테이너 운송에 사용된다.","o":"폴 트레일러는 장척물(대형 파이프·H형강 등) 수송용.","src":"기출 2026-16"}]},"#4":{"묶음":[{"머리":"운수사업의 종류와 정의","줄":[{"t":"화물자동차 운수사업: 화물자동차 운송사업, 화물자동차 운송주선사업, 화물자동차 운송가맹사업","src":"화물자동차 운수사업법 제2조 제2호"},{"t":"운송사업: 다른 사람의 요구에 응하여 화물자동차를 사용해 화물을 유상으로 운송하는 사업","src":"화물자동차 운수사업법 제2조 제3호"},{"t":"운송주선사업: 다른 사람의 요구에 응하여 유상으로 화물운송계약을 중개·대리하거나, 운송사업·운송가맹사업자의 운송수단을 이용해 자기 명의와 계산으로 화물을 운송하는 사업","src":"화물자동차 운수사업법 제2조 제4호"},{"t":"운송가맹사업: 다른 사람의 요구에 응하여 자기 화물자동차로 유상 운송하거나, 화물정보망을 통해 소속 운송가맹점에 의뢰해 운송하게 하는 사업","src":"화물자동차 운수사업법 제2조 제5호"},{"t":"운수종사자: 화물자동차 운전자, 화물 운송·운송주선 사무원 및 보조원, 그 밖에 운수사업 종사자","src":"화물자동차 운수사업법 제2조 제8호"},{"t":"화물차주: 화물을 직접 운송하는 개인 운송사업자와 위·수탁차주","src":"화물자동차 운수사업법 제2조 제11호"},{"t":"안전운송원가: 화물차주에 대한 적정 운임 보장으로 과로·과속·과적을 막기 위해 운임 산정 때 참고하는 운송원가. 안전운임위원회 심의·의결을 거쳐 국토교통부장관이 공표","src":"화물자동차 운수사업법 제2조 제12호"},{"t":"안전운송운임: 화주가 운수사업자 또는 화물차주에게 지급해야 하는 최소한의 운임. 안전위탁운임: 운수사업자가 화물차주에게 지급해야 하는 최소한의 운임","src":"화물자동차 운수사업법 제2조 제13호"}]},{"머리":"운송사업 허가","줄":[{"t":"운송사업을 경영하려는 자는 국토교통부장관의 허가를 받아야 한다","src":"화물자동차 운수사업법 제3조 제1항, 기출 2025-1"},{"t":"일반화물자동차 운송사업: 20대 이상(영 제3조 제1항)의 화물자동차로 화물을 운송하는 사업","src":"화물자동차 운수사업법 제3조 제1항 제1호, 시행령 제3조 제1항"},{"t":"개인화물자동차 운송사업: 화물자동차 1대를 사용해 화물을 운송하는 사업(대통령령으로 정하는 사업)","src":"화물자동차 운수사업법 제3조 제1항 제2호, 기출 2025-1"},{"t":"운송가맹사업 허가를 받은 자는 운송사업 허가를 따로 받지 않는다","src":"화물자동차 운수사업법 제3조 제2항"},{"t":"허가사항 변경은 국토교통부장관의 변경허가. 경미한 사항은 신고. 변경신고는 받은 날부터 3일 이내에 수리 여부를 통지하고, 통지가 없으면 기간 끝난 다음 날 수리한 것으로 본다","src":"화물자동차 운수사업법 제3조 제3항~제5항"},{"t":"경미한 변경사항(신고): 상호 변경, 대표자 변경(법인만), 화물취급소 설치·폐지, 화물자동차 대폐차, 주사무소·영업소·화물취급소 이전(주사무소는 관할 관청 행정구역 내 이전만)","src":"화물자동차 운수사업법 시행령 제3조 제2항"},{"t":"허가기준에 관한 사항은 허가받은 날부터 5년마다 신고","src":"화물자동차 운수사업법 제3조 제9항, 시행령 제3조 제3항"},{"t":"주사무소 외의 장소에 상주하여 영업하려면 국토교통부장관의 허가를 받아 영업소를 설치한다. 개인 운송사업자는 예외","src":"화물자동차 운수사업법 제3조 제11항"},{"t":"사업정지처분을 받은 운송사업자에게는 주사무소 이전 변경허가를 하지 않는다","src":"화물자동차 운수사업법 제3조 제15항"},{"t":"일반화물자동차 운송사업 허가기준: 허가기준 대수 20대 이상, 사무실·영업소는 영업에 필요한 면적, 최저보유차고면적은 1대당 길이×너비","src":"화물자동차 운수사업법 시행규칙 별표 1"},{"t":"개인화물자동차 운송사업 허가기준: 허가기준 대수 1대, 사무실·영업소 없음, 차고면적은 해당 차량의 길이×너비","src":"화물자동차 운수사업법 시행규칙 별표 1"},{"t":"차고는 자기 소유여야 한다. 화물터미널·물류단지 주차장 계약, 국공유지, 1년 이상 장기 임대 등은 자기 소유로 본다","src":"화물자동차 운수사업법 시행규칙 별표 1 비고 2"},{"t":"관할관청은 필요하다고 인정하면 보유차고면적 기준을 기준면적의 2분의 1 범위에서 줄일 수 있다","src":"화물자동차 운수사업법 시행규칙 별표 1 비고 7"}]},{"머리":"운송주선사업","줄":[{"t":"운송주선사업을 경영하려는 자는 국토교통부장관의 허가를 받는다. 운송가맹사업 허가를 받은 자는 따로 받지 않는다","src":"화물자동차 운수사업법 제24조 제1항"},{"t":"허가사항 변경은 신고. 변경신고는 받은 날부터 5일 이내에 수리 여부를 통지한다","src":"화물자동차 운수사업법 제24조 제2항·제3항"},{"t":"주선사업 허가기준: 공급기준에 맞을 것, 사무실 면적 등 국토교통부령 기준(사무실은 영업에 필요한 면적)","src":"화물자동차 운수사업법 제24조 제6항, 시행규칙 별표 4"},{"t":"운송주선사업자는 자기 명의로 다른 사람에게 운송주선사업을 경영하게 할 수 없다(명의이용 금지)","src":"화물자동차 운수사업법 제25조"},{"t":"운송주선사업자 준수사항: 자기 명의로 계약한 화물을 계약금액 일부를 제외한 금액으로 다른 주선사업자와 재계약해 운송하게 해서는 안 된다","src":"화물자동차 운수사업법 제26조 제1항"},{"t":"화주로부터 중개·대리를 의뢰받은 화물을 다른 주선사업자에게 수수료 등 대가를 받고 중개·대리 의뢰해서는 안 된다","src":"화물자동차 운수사업법 제26조 제2항"},{"t":"운송사업자에게 화물의 종류·무게·부피를 거짓으로 통보하거나 도로법·도로교통법 기준을 위반하는 화물의 운송을 주선해서는 안 된다","src":"화물자동차 운수사업법 제26조 제4항"}]},{"머리":"운송가맹사업","줄":[{"t":"운송가맹사업을 경영하려는 자는 국토교통부장관의 허가를 받는다. 허가·변경허가 신청과 변경신고는 20일 이내에 허가·수리 여부를 통지한다","src":"화물자동차 운수사업법 제29조 제1항·제6항"},{"t":"허가기준 대수: 50대 이상(운송가맹점이 소유한 차량 포함), 8개 이상의 시·도에 각각 5대 이상 분포","src":"화물자동차 운수사업법 시행규칙 별표 5"},{"t":"사무실 및 영업소는 영업에 필요한 면적. 최저보유차고면적은 1대당 길이×너비(직접 소유하는 경우만)","src":"화물자동차 운수사업법 시행규칙 별표 5"},{"t":"화물자동차의 종류는 시행규칙 제3조의 화물자동차(직접 소유하는 경우만). 그 밖의 운송시설로 화물정보망을 갖출 것","src":"화물자동차 운수사업법 시행규칙 별표 5"},{"t":"운송사업자가 가맹사업 허가를 신청할 때 운송사업자 지위에서 보유하던 차량은 가맹사업 허가기준 대수로 겸용할 수 없다","src":"화물자동차 운수사업법 시행규칙 별표 5 비고 3"},{"t":"화물정보망은 물량배정 여부·공차 위치 등을 확인할 수 있어야 하고 운임 지급 등 결제시스템이 구축되어야 한다","src":"화물자동차 운수사업법 시행규칙 별표 5 비고 1"}]},{"머리":"책임·보험·준수사항","줄":[{"t":"운송사업자의 적재물사고(멸실·훼손·인도 지연) 손해배상책임은 상법 제135조를 준용한다","src":"화물자동차 운수사업법 제7조 제1항"},{"t":"화물이 인도기한이 지난 후 3개월 이내에 인도되지 않으면 멸실된 것으로 본다","src":"화물자동차 운수사업법 제7조 제2항"},{"t":"국토교통부장관은 화주가 요청하면 손해배상 분쟁을 조정할 수 있고, 업무를 한국소비자원 또는 등록 소비자단체에 위탁할 수 있다. 쌍방이 조정안을 수락하면 합의가 성립한 것으로 본다","src":"화물자동차 운수사업법 제7조 제3항~제6항"},{"t":"적재물배상보험등 의무가입: 최대 적재량 5톤 이상이거나 총중량 10톤 이상인 화물자동차(국토교통부령으로 정하는 차량)를 소유한 운송사업자, 국토교통부령으로 정하는 화물을 취급하는 운송주선사업자, 운송가맹사업자","src":"화물자동차 운수사업법 제35조"},{"t":"운수종사자 금지행위: 정당한 사유 없이 화물을 중도에 내리게 하는 행위, 운송 거부, 부당한 운임·요금 요구, 자동차관리사업자와 부정한 금품 수수, 오랜 시간 정차해 호객, 문을 덜 닫고 출발·운행, 택시 유사표시, 최고속도제한장치 무단 해체·조작","src":"화물자동차 운수사업법 제12조 제1항"},{"t":"업무개시 명령: 운송사업자나 운수종사자가 정당한 사유 없이 집단으로 화물운송을 거부해 국가경제에 심각한 위기를 초래할 우려가 있으면 국토교통부장관이 명한다. 국무회의 심의를 거치고, 국회 소관 상임위원회에 보고한다","src":"화물자동차 운수사업법 제14조"},{"t":"화물운송 종사자격증은 빌려주거나 빌려서는 안 되고 알선도 금지","src":"화물자동차 운수사업법 제8조 제3항~제5항"},{"t":"화주·운송사업자·주선업자 등 운행을 지시·감독하는 자는 운전자에게 도로법 운행제한을 위반해 운행하도록 지시·요구하거나 적재 화물의 중량을 사실과 다르게 알려서는 안 된다","src":"도로법 제77조 제3항"}]},{"머리":"운행상 안전기준(도로교통법 시행령)","줄":[{"t":"승차인원: 승차정원 이내","src":"도로교통법 시행령 제22조 제1호"},{"t":"화물자동차 적재중량: 구조 및 성능에 따르는 적재중량의 110퍼센트 이내","src":"도로교통법 시행령 제22조 제3호"},{"t":"적재용량 길이: 자동차 길이에 그 길이의 10분의 1을 더한 길이를 넘지 않을 것","src":"도로교통법 시행령 제22조 제4호 가목"},{"t":"적재용량 너비: 후사경으로 뒤쪽을 확인할 수 있는 범위의 너비를 넘지 않을 것","src":"도로교통법 시행령 제22조 제4호 나목"},{"t":"적재용량 높이: 화물자동차는 지상으로부터 4미터(고시한 도로노선은 4미터 20센티미터), 소형 3륜자동차 2미터 50센티미터, 이륜자동차 2미터","src":"도로교통법 시행령 제22조 제4호 다목"}]},{"머리":"도로법상 운행 제한 차량","줄":[{"t":"도로관리청이 운행을 제한할 수 있는 차량: 축하중 10톤 초과 또는 총중량 40톤 초과","src":"도로법 시행령 제79조 제2항 제1호"},{"t":"폭 2.5미터 초과, 높이 4.0미터 초과(고시 도로는 4.2미터), 길이 16.7미터 초과","src":"도로법 시행령 제79조 제2항 제2호"},{"t":"그 밖에 도로 구조 보전과 통행 안전에 지장이 있다고 도로관리청이 인정하는 차량도 제한 가능","src":"도로법 시행령 제79조 제2항 제3호"},{"t":"제한 기준을 넘어도 도로관리청의 허가를 받아 운행하는 차량은 제한 대상에서 제외","src":"도로법 제77조 제1항 단서"},{"t":"운행 제한 판단 예: 축하중 8톤은 제한 대상이 아니다. 총중량 50톤, 폭 2.8미터, 높이 5.0미터, 길이 17.0미터는 제한 대상","src":"기출 2026-17, 2022-11"}]},{"머리":"중량 용어(출제 용어 정리)","줄":[{"t":"공차중량: 화물을 싣지 않고 연료·냉각수·윤활유 등을 가득 채운 상태의 중량","src":"기출 2024-35, 2026-20"},{"t":"최대적재중량: 화물을 최대로 적재할 수 있도록 허용된 중량","src":"기출 2026-20, 2024-35"},{"t":"자동차연결 총중량: 최대적재중량에 트레일러와 트랙터의 무게까지 합산한 중량","src":"기출 2026-20, 2024-35"},{"t":"차량 총중량: 차량중량 + 화물적재량 + 승차중량","src":"기출 2025-4, 보충"},{"t":"최대접지압력: 최대 적재상태에서 도로 지면 접지부에 미치는 압력의 정도(공차 상태 기준이 아니다)","src":"기출 2024-35, 2026-20"},{"t":"화물자동차 운전자는 운행상의 안전기준을 준수해야 한다","src":"기출 2026-20"}]}],"함정":[{"x":"축간 중량 5톤 초과 / 길이 13.7m 초과 / 너비 2.0m 초과 / 높이 3.5m 초과 (운행제한 기준 문항의 오답 선지)","o":"축하중 10톤, 폭 2.5m, 높이 4.0m, 길이 16.7m 초과. 총중량은 40톤 초과가 정답.","src":"기출 2022-11"},{"x":"적재중량: 승차인원은 승차정원의 110 % 이내일 것","o":"승차인원은 승차정원 이내. 110%는 적재중량 기준.","src":"기출 2023-9"},{"x":"높이: 지상으로부터 4.5미터를 넘지 아니할 것","o":"화물자동차 높이 기준은 4미터(고시 도로 4.2미터).","src":"기출 2023-9"},{"x":"허가기준대수: 400대 이상(운송가맹점이 소유하는 화물자동차 대수를 포함하되, 8개 이상의 시ㆍ도에 50대 이상 분포되어야 한다)","o":"50대 이상, 8개 이상의 시·도에 각각 5대 이상.","src":"기출 2023-10, 화물자동차 운수사업법 시행규칙 별표 5"},{"x":"최대적재중량은 화물자동차 자체중량과 최대 승차중량을 합한 중량을 말한다.","o":"최대적재중량은 화물을 최대로 적재할 수 있도록 허용된 중량.","src":"기출 2024-35, 2026-20"},{"x":"자동차연결 총중량은 공차상태에서 트랙터와 트레일러까지 합산된 중량을 말한다.","o":"최대적재중량에 트레일러와 트랙터 무게까지 합산한 중량.","src":"기출 2024-35"},{"x":"화물자동차의 운송능력은 공차중량에 자동차의 평균 용적을 곱하여 계산한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-35"},{"x":"최대접지압력은 공차상태에서 도로 지면 접지부에 미치는 압력의 정도를 말한다.","o":"최대 적재상태 기준.","src":"기출 2024-35, 2026-20"},{"x":"제3자 물류 활성화를 위해 운송주선사업자는 자기 명의로 다른 사람에게 화물자동차 운송주선사업을 경영하게 할 수 있다.","o":"자기 명의로 다른 사람에게 주선사업을 경영하게 할 수 없다.","src":"기출 2025-1, 화물자동차 운수사업법 제25조"},{"x":"최대적재량이 3톤 이상이거나 총 중량이 10톤 이상인 화물자동차는 적재물배상 보험에 가입하여야 한다.","o":"최대 적재량 5톤 이상이거나 총중량 10톤 이상.","src":"기출 2025-4, 화물자동차 운수사업법 제35조"},{"x":"차량 총중량은 차량중량과 화물적재량의 합에서 승차중량을 제외한 것이다.","o":"차량중량 + 화물적재량 + 승차중량.","src":"기출 2025-4, 보충"},{"x":"2차축 차량의 축 화물중량은 공차 시 전축 중량과 영차 시 화중을 합산한 중량이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-4"},{"x":"공차 중량은 화물을 적재하지 않고 연료, 냉각수, 윤활유 등을 채우지 않은 상태의 화물차량 중량을 말한다.","o":"연료·냉각수·윤활유 등을 가득 채운 상태.","src":"기출 2025-4, 2024-35, 2026-20"},{"x":"허가기준 대수는 50대 이상이며 운송사업자가 화물자동차 운송가맹사업 허가를 신청하는 경우 운송사업자의 지위에서 보유하고 있던 운송사업용 화물자동차는 가맹사업의 허가기준 대수로 겸용할 수 있다.","o":"겸용할 수 없다.","src":"기출 2025-19, 화물자동차 운수사업법 시행규칙 별표 5 비고 3"},{"x":"최대접지압력은 최대 적재상태에서 트랙터를 제외한 연결 접지부에 미치는 압력의 정도이다.","o":"출제 오답(바른 수치 미확인). 접지부 압력은 최대 적재상태 기준.","src":"기출 2026-20"}]},"#5":{"묶음":[{"머리":"채트반(Chatban) 공식","줄":[{"t":"용도: 화물자동차 운송과 철도운송 중 어느 쪽이 경제적인지 가르는 경제효용거리(분기점) 계산","src":"기출 2022-8"},{"t":"공식: 분기점 거리(km) = 철도 부대비용(원/ton) ÷ (자동차 운송비 − 철도 운송비)(원/ton·km 기준)","src":"기출 2021-2, 2023-17, 2024-22, 2025-12, 2026-31"},{"t":"철도 부대비용에는 철도발착비(상하차비), 하역비, 배송비, 포장비 등이 들어간다","src":"기출 2021-2, 2026-31"},{"t":"풀이 순서: 자동차 운송비와 철도 운송비의 차를 구한다, 철도 부대비용을 그 차로 나눈다","src":"기출 2021-2"},{"t":"계산 예: 900원과 500원, 부대비용 50,000원이면 50,000 ÷ 400 = 125km","src":"기출 2021-2"},{"t":"계산 예: 80원과 40원, 부대비용 10,000원이면 10,000 ÷ 40 = 250km","src":"기출 2023-17"},{"t":"계산 예: 10,000원과 5,000원, 부대비용 500,000원이면 500,000 ÷ 5,000 = 100km","src":"기출 2024-22"},{"t":"계산 예: 4,000원과 2,000원, 부대비용 500,000원이면 500,000 ÷ 2,000 = 250km","src":"기출 2025-12"},{"t":"계산 예: 3,000원과 1,000원, 부대비용 1,000,000원이면 1,000,000 ÷ 2,000 = 500km(1,000km가 아니다)","src":"기출 2026-31"},{"t":"분기점 이내(짧은 거리)에서는 화물자동차가 유리하고, 분기점을 넘는 장거리에서는 철도가 유리하다","src":"기출 2022-8"},{"t":"분기점 방향: 철도 부대비용이 늘면 분기점이 커진다. 자동차 운송비가 늘면 분모가 커져 분기점이 줄어든다. 철도 운송비가 늘면 분모가 줄어 분기점이 커진다","src":"기출 2026-31"}]},{"머리":"운영 효율 지표","줄":[{"t":"가동률 = 실제 가동 차량 수 ÷ 실제 차량 수 × 100. 특정 기간 중 화물운송을 위해 운행한 일수의 비율로도 산출. 예: 270 ÷ 300 = 90%","src":"기출 2021-15, 2024-30"},{"t":"영차율(실차율) = 실제 적재 주행거리 ÷ 총(누적) 주행거리 × 100. 예: 63,000 ÷ 70,000 = 90%, 21,000 ÷ 30,000 = 70%","src":"기출 2021-15, 2024-23"},{"t":"적재율 = 평균 적재중량 ÷ 적재 가능 총중량 × 100. 예: 4 ÷ 5 = 80%, 8.5 ÷ 10 = 85%","src":"기출 2021-15, 2024-23, 2024-30"},{"t":"공차거리율 = 빈 차 상태의 운행거리 ÷ 전체 운행거리 × 100. 예: 누적 30,000km 중 적재 21,000km이면 공차 9,000 ÷ 30,000 = 30%","src":"기출 2026-12, 2021-15"},{"t":"복화율: 편도 운송을 한 뒤 복귀할 때 화물운송을 얼마나 수행했는지 나타내는 지표","src":"기출 2024-30"},{"t":"회전율: 특정 기간 내에 화물을 운송한 횟수로 산출","src":"기출 2024-30"},{"t":"공차율은 빈 차로 달린 정도를 나타내는 지표다. 총 운송매출 중 무료로 운송한 비중이 아니다","src":"기출 2024-30"},{"t":"운영 효율화 원칙: 가동률 최대화, 영차율(실차율) 최대화, 회전율 최대화, 적재율 최대화, 공차율 최소화, 운송단위 대형화","src":"기출 2021-6, 2024-2"}]},{"머리":"운송 효율화 방안","줄":[{"t":"운송정보시스템 구축, 도로 및 기간시설 확충, 컨테이너·파렛트 운송 확대, 공동배송체제 구축·확대","src":"기출 2021-19"},{"t":"수리·정비로 가동성 향상, 신규 화주 계약으로 적재율 향상, 대형 차량으로 운송단위 대형화, 대기·상하차 시간 단축으로 운송시간 단축","src":"기출 2024-2"},{"t":"화물자동차 운송시스템 전략 원칙: 운송과 재고의 Trade-off, 단일 원거리 운송, 수배송 일원화, 상하차 신속","src":"기출 2025-13"},{"t":"회전수는 늘리는 쪽이 원칙이다. 회전수 감소는 원칙에 들지 않는다","src":"기출 2025-13"}]},{"머리":"운송원가: 고정비와 변동비","줄":[{"t":"고정비: 감가상각비, 지급이자, 자동차보험료, 차고지 월임대료","src":"기출 2022-13, 2025-14, 2026-13"},{"t":"변동비: 유류비, 타이어 교체비(타이어비), 수리비, 윤활유비, 도로통행료(톨게이트 통행료), 시간외 수당","src":"기출 2022-13, 2024-33, 2025-14, 2026-13"},{"t":"운송거리·운행에 비례해 늘어나는 비용이 변동비, 운행과 무관하게 일정하게 나가는 비용이 고정비","src":"기출 2022-13, 2025-14"},{"t":"연료소모량 계산 순서: 공차 운행거리 × 공차 연비(L/km) + 영차 운행거리 × 평균 적재량 × 영차 연비(L/ton·km)","src":"기출 2021-20"},{"t":"계산 예: 총 36,000km, 영차 28,000km이면 공차 8,000km. 8,000 × 0.3 = 2,400L, 28,000 × 18톤 × 0.5 = 252,000L, 합계 254,400L","src":"기출 2021-20"}]}],"함정":[{"x":"채트반 공식으로 산출된 경계점 거리이내에서는 화물자동차운송보다 철도운송이 유리하다.","o":"경계점 이내에서는 화물자동차가 유리하고 초과하면 철도가 유리.","src":"기출 2022-8"},{"x":"공차율은 화물자동차의 총 운송매출 중에서 무료로 얼마나 운송했는지를 나타내는 지표이다.","o":"공차율은 빈 차로 운행한 정도를 나타내는 지표.","src":"기출 2024-30"},{"x":"소형차량을 이용하는 소형화 원칙 / 영차율 최소화 원칙 / 회전율 최소화 원칙 / 적재율 최소화 원칙 (효율화 원칙 문항의 오답 선지)","o":"대형화, 영차율·회전율·적재율 최대화, 가동률 최대화.","src":"기출 2021-6"},{"x":"적재율 감소 및 차량의 배송 빈도 증가 (효율화 방안 문항의 오답 선지)","o":"적재율은 높이고 배송 빈도는 줄인다.","src":"기출 2021-19"},{"x":"새로운 운송방법 도입으로 화물자동차의 공차율 극대화","o":"공차율은 최소화.","src":"기출 2024-2"},{"x":"회전수 감소의 원칙 (운송시스템 전략 원칙 문항의 오답 선지)","o":"회전수는 증대.","src":"기출 2025-13"},{"x":"유류비·수리비·윤활유비·도로통행료는 고정비이다.","o":"고정비는 감가상각비 등. 이들은 변동비.","src":"기출 2022-13"},{"x":"유류비(ㄷ)·타이어비(ㄹ)·시간외 수당(ㅁ)은 고정비다.","o":"고정비는 감가상각비와 지급이자(ㄱ, ㄴ).","src":"기출 2025-14"},{"x":"채트반 분기점은 1,000km이다 (철도 부대비용 1,000,000원, 철도 1,000원, 자동차 3,000원 조건).","o":"1,000,000 ÷ 2,000 = 500km.","src":"기출 2026-31"},{"x":"화물자동차 운송비가 증가할수록 경제효용거리 분기점은 증가한다.","o":"자동차 운송비가 늘면 분모가 커져 분기점은 줄어든다.","src":"기출 2026-31"}]},"#6":{"묶음":[{"머리":"철도화물운송 형태와 하역방식","줄":[{"t":"철도화물운송 형태: 화차취급운송, 컨테이너취급운송 등","src":"기출 2021-21, 2025-11"},{"t":"전세열차: 고객이 특정 열차를 전용으로 사용하는 열차","src":"기출 2025-11"},{"t":"컨테이너의 철도운송 방식은 TOFC와 COFC 두 가지","src":"기출 2021-21"},{"t":"TOFC: 트레일러째 화차에 싣는 방식. 피기백(Piggy Back)방식과 캥거루(Kangaroo)방식이 여기에 속한다","src":"기출 2021-21, 2024-9"},{"t":"COFC: 컨테이너 자체만 화차에 상·하차하는 방식. 하역이 쉽고 화차 중량이 가벼워 보편화되었다. 상·하차에 별도 장비가 필요하다","src":"기출 2024-9"}]},{"머리":"철도운송 서비스(열차) 형태","줄":[{"t":"Block Train: 철도화물역·터미널 간을 직행 운행하는 전용열차. 스위칭야드를 이용하지 않고 최초 출발역에서 최종 도착역까지 직송. 화차의 수와 타입이 고정되어 있지 않다. 철도-도로 복합운송에서 많이 쓴다","src":"기출 2022-16, 2023-20, 2026-23"},{"t":"Shuttle Train: 화차조성비용을 줄이기 위해 화차의 수와 타입이 고정되고, 출발지→목적지→출발지를 잇는 루프형 서비스. 비교적 짧은 구간에 유용","src":"기출 2023-20, 2025-18"},{"t":"Y-Shuttle Train: 한 개의 중간터미널을 거치는 점만 빼고 Shuttle Train과 같다","src":"기출 2023-20"},{"t":"Single-Wagon Train: 복수의 중간역·터미널을 거치며 운행. 경로상 모든 종류의 화차·화물을 수송. 화주가 원하는 시간이 아니라 열차편성이 가능한 물량이 확보될 때만 운행. 철도운송 서비스 중 가장 높은 비중. Liner Train이 이 서비스의 한 종류","src":"기출 2021-8, 2023-20, 2024-10, 2026-23"},{"t":"Liner Train: 장거리구간에 소규모 터미널이 여럿일 때 여객열차처럼 각 터미널에서 화차를 Pick up & Deliver하는 서비스","src":"기출 2023-20"},{"t":"Coupling & Sharing Train도 열차 서비스 형태의 하나로 문항에 선지로 나온다","src":"기출 2022-16, 2024-10"}]},{"머리":"컨테이너 운송용 화차와 화차 종류","줄":[{"t":"컨테이너 운송에 쓰는 화차: Open top car, Flat car, Container car, Double stack car. Covered hopper car와 Tank car는 컨테이너용이 아니다","src":"기출 2021-4, 2023-18"},{"t":"호퍼화차가 아니라 유개화차: 포대화물·종이류 수송, 양측 슬라이딩 도어로 적하가 쉽다","src":"기출 2025-16, 보충"},{"t":"곡물화차: 양곡·사료 등 비포장 분말화물을 상부 해치로 적재하고 하부 호퍼로 하역","src":"기출 2025-16"},{"t":"무개화차: 지붕이 없는 화차. 석탄·자갈 등 손상 염려가 없는 화물 수송","src":"기출 2025-16"},{"t":"컨테이너 화차: 상면 위에 컨테이너를 싣고 고정장치가 붙어 있다","src":"기출 2025-16"},{"t":"곡형평면화차: 특대형 화물용. 중앙부가 저상구조로 대형 변압기·군장비를 싣는다","src":"기출 2025-16"}]},{"머리":"철도 화물운임","줄":[{"t":"철도화물 운임체계: 일반화물과 컨테이너 화물로 구분","src":"기출 2025-17"},{"t":"일반화물 기본운임: 1건마다 중량, 거리, 임률을 곱해 계산. 1건 기본운임이 최저기본운임에 못 미치면 최저기본운임을 기본운임으로 한다","src":"기출 2021-3, 2023-19"},{"t":"화차 1량의 최저기본운임: 사용 화차의 화차표기하중톤수의 100km에 해당하는 운임(200km가 아니다)","src":"기출 2023-19, 보충"},{"t":"컨테이너화물 운임 = 컨테이너 규격별 운임단가(원/km) × 운송거리(km). 컨테이너 크기·적컨테이너·공컨테이너에 따라 1km당 운임률이 다르다","src":"기출 2021-3, 2023-19"},{"t":"컨테이너화물의 최저기본운임: 규격별(영·공별) 컨테이너의 100km에 해당하는 운임","src":"기출 2021-3, 2025-17"},{"t":"공컨테이너 운임은 규격별로 정해진 단가를 쓴다. 영컨테이너 운임의 50%를 적용한다고 단정하지 않는다","src":"기출 2021-3"},{"t":"할인 종류: 왕복수송 할인, 탄력할인, 사유화차 할인. 사유화차로 운송하면 할인운임","src":"기출 2021-3, 2023-19, 2025-17"},{"t":"사유화차 할인: 고객이 화차를 제작해 철도운송에 사용할 때 투자비 보전을 위한 할인. 할인율은 화차 제작 조건에 따라 다르다","src":"기출 2025-17"},{"t":"화차취급운임 중 정량화된 대량화물·파렛트 화물 운송은 할인","src":"기출 2022-17"},{"t":"할증 대상: 귀중품, 위험물(위험화물), 특대화물, 냉동컨테이너, 철도공사 직원이 감시인으로 승차하는 화물, 열차 및 경로 지정화물","src":"기출 2022-17, 2023-19, 2025-17"},{"t":"운임 구성: 화차(차량)취급운임, 컨테이너 취급운임, 혼재운임","src":"기출 2022-17"}]},{"머리":"철도운송 일반 특징","줄":[{"t":"국내 화물 수송분담률(ton·km 기준)은 공로가 철도보다 높다","src":"기출 2021-21, 2025-11"},{"t":"기후 영향이 적고 계획적 운송이 가능하다. 교통체증 영향도 적다","src":"기출 2021-21, 2025-11"},{"t":"장거리 대량화물에 유리하고 전국 네트워크가 있다. 타 수단과 연계 없이는 Door to Door가 안 된다","src":"기출 2022-19"}]}],"함정":[{"x":"공컨테이너의 운임은 규격별 영(적재)컨테이너 운임의 50 %를 적용하여 계산 한다.","o":"출제 오답(바른 수치 미확인). 공컨테이너는 규격별·영공별 단가로 계산한다.","src":"기출 2021-3"},{"x":"COFC 방식에는 피기백방식과 캥거루방식이 있다.","o":"피기백·캥거루는 TOFC 방식.","src":"기출 2021-21"},{"x":"공컨테이너와 적컨테이너의 운송은 할증이 적용된다.","o":"할증은 냉동컨테이너 등. 공·적 컨테이너 일반 운송에는 할증하지 않는다.","src":"기출 2022-17"},{"x":"화차 1량에 대한 최저기본운임은 사용화차의 화차표기하중톤수의 200 km에 해당하는 운임이다.","o":"100km에 해당하는 운임.","src":"기출 2023-19, 보충"},{"x":"화차의 소재관리가 편리하여 열차편성을 신속히 할 수 있다.","o":"화차 소재관리가 불편해 열차편성이 느리다.","src":"기출 2024-17"},{"x":"호퍼화차는 포대화물, 종이류 등을 수송하기 위한 차량으로 양측에 슬라이딩 도어를 구비하여 화물의 적하가 용이하도록 되어 있다.","o":"설명은 유개화차.","src":"기출 2025-16, 보충"},{"x":"사유화차 할인은 고객이 화차를 제작하여 철도운송에 사용할 경우 투자비 보전을 위해 시행하는 할인으로 할인율은 화차제작 조건에 관계없이 동일하게 적용된다.","o":"화차 제작 조건에 따라 할인율이 다르다.","src":"기출 2025-17"},{"x":"국내의 수송수단별 화물수송 분담률에서 tonㆍkm기준으로 철도운송이 공로운송 보다 분담률이 높다.","o":"공로가 더 높다.","src":"기출 2025-11"},{"x":"Block Train: 화차의 수와 타입이 고정되어 있음 (옳지 않은 선지)","o":"Block Train은 화차의 수와 타입이 고정되어 있지 않다. 고정되는 것은 Shuttle Train.","src":"기출 2023-20, 2022-16"}]},"#7":{"묶음":[{"머리":"정기선 할증료","줄":[{"t":"BAF(Bunker Adjustment Factor): 선박 연료인 벙커유 가격 변동에 따른 손실을 보전하는 할증료","src":"기출 2021-24"},{"t":"CAF(Currency Adjustment Factor): 급격한 환율변동으로 선사가 입는 환차손을 보전하는 할증료","src":"기출 2021-24"},{"t":"Congestion Surcharge: 특정 항구의 하역능력 부족으로 체선이 생겨 장기간 정박해야 할 때 해당 화물에 붙이는 할증료","src":"기출 2021-24"},{"t":"Transshipment Surcharge: 화물이 운송 도중 환적될 때 드는 추가비용을 보전하는 할증료","src":"기출 2021-24"},{"t":"Outport Surcharge는 양륙항을 변경하는 화물 할증료가 아니다. 양륙항 변경·선택에 붙는 것은 Optional(양륙항 선택) 할증료","src":"기출 2021-24, 보충"}]},{"머리":"선박 국적과 선적제도","줄":[{"t":"전통적 선박 국적 취득 요건: 자국민 소유, 자국 건조, 자국민 승선","src":"기출 2022-21"},{"t":"편의치적(FOC): 선주가 실제 소유국이 아닌 나라에 선박을 등록하는 제도. 세제 혜택과 금융조달의 용이성으로 확대. 자국의 엄격한 선박운항·안전기준에서 벗어날 수 있다","src":"기출 2022-21"},{"t":"제2선적제도: 기존 전통 선적제도를 유지한 채 역외등록제도·국제선박등록제도를 추가로 두는 방식. 우리나라가 시행","src":"기출 2022-21"}]},{"머리":"해운동맹(Conference)","줄":[{"t":"해운동맹: 2개 이상의 정기선 운항업자가 경쟁을 제한·조정하기 위해 운임, 적취량, 배선 등의 조건에 합의한 국제카르텔","src":"기출 2023-23"},{"t":"가입·탈퇴에 따라 개방동맹과 폐쇄동맹으로 구분한다. 미국을 포함한 대부분 국가가 해운동맹을 적극 수용하는 것은 아니다","src":"기출 2023-23"},{"t":"동맹회원 간에는 운임표가 의무적으로 적용되지만 특정 화물에는 자유로운 open rate이 가능","src":"기출 2023-23"},{"t":"동맹 운영방법: 공동계산협정(Pooling Agreement) — 일정기간 벌어들인 운임을 사전에 정한 배분율에 따라 배분. 운임수입에서 소정의 비용을 공제한 금액의 전부 또는 일부를 각사에 나눈다","src":"기출 2025-34"},{"t":"맹외선(비동맹선) 대응 수단: 대항선(Fighting Ship) 운영, 계약운임제(Contract Rate System, 이중운임제), 성실환급제(Fidelity Rebate System), 이연환급제(Deferred Rebate System)","src":"기출 2025-34, 2023-23, 보충"}]},{"머리":"운임톤과 용적 기준","줄":[{"t":"Revenue Ton(R/T): 무게 기준 중량톤과 부피 기준 용적톤을 각각 산출해, 원칙적으로 운송인에게 유리한 쪽을 운임단위로 적용","src":"기출 2022-20"},{"t":"Long Ton(L/T)=2,240lb, Short Ton(S/T)=2,000lb, Metric Ton(M/T)=1,000kg. Gross Ton은 총톤수","src":"기출 2022-20, 보충"},{"t":"용적기준 운임: 양모·면화·코르크·목재·자동차처럼 중량에 비해 부피가 큰 화물, Drum·Barrel·Roll처럼 화물 사이에 공간이 생기는 화물에 적용. 손실공간을 포함한 적화계수를 적용","src":"기출 2022-9, 2024-33"}]},{"머리":"선박의 톤수","줄":[{"t":"선박의 톤은 중량과 용적 두 가지 단위로 나타낸다","src":"기출 2025-31"},{"t":"용적톤수: 총톤수(GT), 순톤수(NT)","src":"기출 2025-31"},{"t":"순톤수: 총톤수에서 기관실·선원실 등 선박 운항과 관련된 장소의 용적을 제외한 톤수","src":"기출 2025-31"},{"t":"재화중량톤수(DWT): 선박이 적재할 수 있는 화물의 최대허용중량","src":"기출 2025-31, 보충"},{"t":"배수톤수: 선체 수면아래 부분의 용적에 상당하는 물의 중량","src":"기출 2025-31, 보충"},{"t":"만재흘수선: 화물을 가장 많이 실을 수 있는 선은 열대 담수 목재 만재흘수선(LTF), 가장 적게 싣는 선은 동계 목재 만재흘수선(LW)","src":"기출 2026-24"}]},{"머리":"선박의 종류","줄":[{"t":"Barge Ship: 예인선(Tug Boat)에 끌려가는 무동력 선박","src":"기출 2024-16"},{"t":"Lighter Aboard Ship(LASH): Float-On Float-Off 방식에 특화된 선박","src":"기출 2024-16"},{"t":"Full Container Ship: 건조 단계에서 갑판과 선창에 컨테이너를 싣도록 설계된 선박","src":"기출 2024-16"},{"t":"Lift-On Lift-Off Ship(LO-LO)는 크레인으로 수직 적·양하하는 선박. 선수·선미 램프로 트랙터 등이 적·양하하는 것은 Roll-On Roll-Off(RO-RO)","src":"기출 2024-16, 보충"},{"t":"Combination Ship: 공선항해를 줄이려고 한 척에 2~3종의 화물을 겸용하는 선박","src":"기출 2024-16"}]},{"머리":"해운 일반","줄":[{"t":"해상운송은 떠다니는 영토로 불릴 만큼 국제성이 높고, 제2선적 같은 전략적 지원이 강조된다","src":"기출 2023-21"},{"t":"해상운송은 장거리·대량운송으로 운임부담력이 낮은 화물을 맡아 국제물류의 중심 역할을 한다","src":"기출 2023-21"}]}],"함정":[{"x":"Outport Surcharge는 운송 도중에 당초 지정된 양륙항을 변경하는 화물에 대한 할증료이다.","o":"양륙항 변경·선택에 붙는 할증은 Optional 할증료(보충). Outport는 기본항 외 항구 양륙 관련.","src":"기출 2021-24, 보충"},{"x":"제2선적제도는 기존의 전통적 선적제도를 폐지하고, 역외등록제도와 국제선박등록제도를 신규로 도입한다.","o":"전통 선적제도는 유지하고 병행해 역외·국제선박등록제도를 둔다.","src":"기출 2022-21"},{"x":"두 개 이상의 정기선 운항업자가 경쟁을 활성화하기 위해 운임, 적취량, 배선 등의 조건에 합의한 국제카르텔을 말한다.","o":"경쟁을 제한하기 위한 합의.","src":"기출 2023-23"},{"x":"미국을 포함한 대부분의 국가는 해운동맹을 적극적으로 받아들이고 있으며, 개방동맹과 폐쇄동맹에 대한 차이는 없다.","o":"개방동맹과 폐쇄동맹은 구분된다.","src":"기출 2023-23"},{"x":"해운동맹은 정기선의 운임을 높게 유지함으로써 동맹탈퇴의 잠재이익이 크게 작용하고 있어 동맹유지가 어렵고 이탈이 심한 편이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-23"},{"x":"맹외선과의 대응전략으로 동맹사들은 경쟁억압선의 투입이나 이중운임제, 연체료와 같은 할인할증제 등을 운영한다.","o":"출제 오답(바른 수치 미확인). 대응수단은 대항선·계약운임제·성실환급제·이연환급제.","src":"기출 2023-23, 보충"},{"x":"해상운송은 물품의 파손, 분실, 사고발생의 위험이 적고, 타 운송수단에 비해 안전성이 높다.","o":"위험이 크고 안전성이 낮다.","src":"기출 2023-21, 보충"},{"x":"양모, 면화 등 중량에 비해 부피가 큰 용적화물은 수량기준으로 운임을 산정해야 한다.","o":"용적기준.","src":"기출 2024-33"},{"x":"Lift-On Lift-Off Ship: 본선의 선수 또는 선미에서 트랙터 등에 의해 적ㆍ양하가 이루어지는 선박","o":"설명은 RO-RO. LO-LO는 크레인 수직 적·양하.","src":"기출 2024-16, 보충"},{"x":"소량 다빈도 운송으로 문전수송(Door-to-Door)에 적합하다. (연안운송)","o":"연안운송은 대량 운송, 문전수송에는 맞지 않는다.","src":"기출 2025-32"},{"x":"재화중량톤수는 선체의 수면아래 부분의 용적에 상당하는 물의 중량을 의미한다. / 배수톤수는 선박이 적재할 수 있는 화물의 최대허용중량을 의미한다.","o":"두 설명이 서로 뒤바뀐 것. 재화중량톤수=최대허용 화물중량, 배수톤수=수면 아래 용적에 해당하는 물의 중량.","src":"기출 2025-31, 보충"}]},"#8":{"묶음":[{"머리":"부정기선 특징","줄":[{"t":"화주가 요구하는 시기와 항로에 선복을 제공해 화물을 운송한다. 항로별 운임요율표를 불특정 다수 화주에게 제공하는 것은 정기선","src":"기출 2024-11"},{"t":"주요 대상 화물: 원자재, 연료, 곡물 등. 화물의 특성·형태에 따라 특수 전용선이 도입된다","src":"기출 2024-11"},{"t":"운송계약 형태: 나용선, 항해용선, 정기용선","src":"기출 2024-11"},{"t":"부정기선 운임: 장기계약운임, 현물운임, 공적운임, 연속항해운임. 특별운임은 부정기선 운임이 아니다","src":"기출 2021-38"}]},{"머리":"용선계약 3종 비교","줄":[{"t":"항해용선(Voyage Charter): 선주가 선장을 임명하고 지휘·감독한다. 본선운항에 따른 책임과 비용은 선주가 부담하고 용선자는 운임을 지급","src":"기출 2023-24"},{"t":"정기용선(Time Charter): 선주가 선장을 임명하고 지휘·감독한다. 용선료는 원칙적으로 기간에 따라 결정. 영업상 사정으로 본선이 운항하지 못해도 용선료를 지급","src":"기출 2023-24"},{"t":"나용선(Bareboat Charter): 용선자가 기간을 정해 선박 자체만 임차하고 선장·선원·항비·수선비·보험료 등을 모두 부담. 선장·선원에 대한 지휘·감독권이 용선자에게 있고 이들의 과실 책임도 용선자가 진다","src":"기출 2025-38"},{"t":"선복용선(Lump-sum Charter), 일대용선(Daily Charter)은 나용선이 아닌 다른 용선 형태로 문항에 선지로 나온다","src":"기출 2025-38"}]},{"머리":"용선계약서 조항","줄":[{"t":"Lien Clause(유치권 조항): 선주가 운임·공적운임·체선료 등을 받기 위해 화물과 그 부속물을 유치할 수 있는 권리. 용선료 지급을 확보하기 위한 화물압류 권리","src":"기출 2021-22"},{"t":"그 밖의 조항 예: Indemnity Clause, Not before Clause, Deviation Clause, General Average Clause","src":"기출 2021-22"}]},{"머리":"하역비 부담 조건","줄":[{"t":"Gross Term(Berth Term, Liner Term): 선적항 선측에서 양하항 선측까지 비용과 위험을 선주가 모두 부담. 적·양하비 모두 선주 부담","src":"기출 2023-22, 2026-30"},{"t":"Net Term(Net Term Charter): 하역비, 항비 등을 화주(용선자)가 부담","src":"기출 2026-30"},{"t":"FI(Free In): 적하비는 화주, 양하비는 선주 부담","src":"기출 2026-30, 2023-22"},{"t":"FO(Free Out): 적하비는 선주, 양하비는 화주 부담","src":"기출 2026-30, 2023-22"},{"t":"FIO(Free In and Out): 선적·양륙 모두 용선자(화주)가 하역비 부담. 선주는 하역 관련 비용·위험 책임이 없다","src":"기출 2026-25, 2023-22"}]},{"머리":"정박기간 조건","줄":[{"t":"CQD(Customary Quick Despatch): 특정 항구의 관습적 하역방법에 따라 가능한 조속히 하역","src":"기출 2026-25"},{"t":"SHEX(Sundays and Holidays Excepted): 일요일·공휴일은 작업일에서 제외","src":"기출 2026-25"},{"t":"WWD(Weather Working Days): 작업이 가능한 날짜만 정박기간에 산입","src":"기출 2026-25"},{"t":"Demurrage(체선료): 허용정박기간을 넘겨 하역이 지연될 때 용선자가 선주에게 지급. 허용기간보다 일찍 끝나면 선주가 용선자에게 주는 것은 Despatch(조출료)","src":"기출 2026-25, 보충"}]}],"함정":[{"x":"화물을 선측에서 선내까지 싣는 과정의 비용 및 위험부담은 화주의 책임이며, 양하항에 도착 후 본선에서 부두로 양하할 때의 비용과 위험은 선사가 부담한다. (선주 부담 조건 문항의 오답)","o":"이 설명은 FI 조건. 선주가 모두 부담하는 조건은 Gross(Berth) Term.","src":"기출 2023-22"},{"x":"화물을 본선으로부터 양하하는 위험부담은 화주의 책임이며, 반대로 선사는 적하비용을 부담한다.","o":"이 설명은 FO 조건.","src":"기출 2023-22"},{"x":"화물의 본선 적하 및 양하와 관련된 모든 비용과 위험부담은 화주가 지며, 선사는 아무런 책임을 지지 않는다.","o":"이 설명은 FIO 조건.","src":"기출 2023-22"},{"x":"품목에 관계없이 동일하게 적용되는 운임을 말한다. (하역조건 문항의 오답)","o":"품목 불문 동일 운임은 무차별운임(FAK).","src":"기출 2023-22"},{"x":"항해용선계약의 특성상 용선자는 본선운항에 따른 모든 책임과 비용을 부담하여야 한다.","o":"항해용선에서는 선주가 운항 책임과 비용을 부담한다.","src":"기출 2023-24"},{"x":"항로별 운임요율표가 불특정 다수의 화주에게 제공된다. (부정기선)","o":"정기선의 특징.","src":"기출 2024-11"},{"x":"Demurrage는 허용정박기간 안에 하역이 종료된 경우 지불하는 조건이다.","o":"기간을 넘겼을 때 용선자가 지급하는 체선료. 기간 내 종료 시 지급하는 것은 조출료(Despatch).","src":"기출 2026-25"},{"x":"Berth Term Charter는 적ㆍ양하비 모두 화주가 부담하는 조건이다.","o":"적·양하비 모두 선주 부담.","src":"기출 2026-30"}]},"#9":{"묶음":[{"머리":"선하증권 종류","줄":[{"t":"선적 선하증권(Shipped B/L, On Board B/L): 화물이 증권에 명시된 본선에 선적되었음을 표시","src":"기출 2024-8"},{"t":"무사고 선하증권(Clean B/L): 본선수취증 비고란에 선적화물의 결함 기재가 없을 때 발행","src":"기출 2024-8, 2022-24"},{"t":"사고부 선하증권(Foul B/L): 화물 인수 당시 포장이 불완전하거나 수량이 부족한 사실이 발견되면 발행. 은행이 매입하지 않는다","src":"기출 2022-24"},{"t":"파손화물보상장(Letter of Indemnity, L/I): 송화인이 운송인에게 일체의 클레임을 송화인이 책임진다는 서류를 내고 무사고 선하증권을 받는 데 쓰인다","src":"기출 2022-24"},{"t":"기명식 선하증권(Straight B/L): 수하인란에 수하인의 성명이 적힌 증권","src":"기출 2024-8"},{"t":"스테일 선하증권(Stale B/L): 발행 후 은행이 인정하는 허용 기간 안에 제시되지 못한 증권","src":"기출 2024-8"},{"t":"적색 선하증권(Red B/L)은 복합운송을 증명하는 증권이 아니다. 복합운송 증명은 Through B/L·복합운송증권. Red B/L은 선하증권에 보험 기능이 결합된 증권으로 알려져 있다","src":"기출 2024-8, 보충"},{"t":"Master B/L: 선사가 국제물류주선업자에게 발행. House B/L: 선사 B/L을 근거로 주선업자가 각 LCL 화주에게 발행. Groupage B/L은 선사가 주선업자에게 교부하는 Master B/L","src":"기출 2021-27"}]},{"머리":"원본 B/L 없이 화물 인도받는 방법","줄":[{"t":"수입지에서 원본 선하증권 없이 화물을 찾는 수단: Surrendered B/L, L/G(Letter of Guarantee, 수입화물선취보증장), Sea Waybill","src":"기출 2021-25"},{"t":"Clean Received B/L과 T/R(Trust Receipt)은 이 용도가 아니다","src":"기출 2021-25"}]},{"머리":"선하증권 법적 기재사항(상법 제853조)","줄":[{"t":"선박의 명칭·국적 및 톤수","src":"상법 제853조 제1항 제1호"},{"t":"송하인이 서면으로 통지한 운송물의 종류, 중량 또는 용적, 포장의 종별, 개수와 기호","src":"상법 제853조 제1항 제2호"},{"t":"운송물의 외관상태","src":"상법 제853조 제1항 제3호"},{"t":"용선자 또는 송하인의 성명·상호","src":"상법 제853조 제1항 제4호"},{"t":"수하인 또는 통지수령인의 성명·상호","src":"상법 제853조 제1항 제5호"},{"t":"선적항, 양륙항","src":"상법 제853조 제1항 제6호·제7호"},{"t":"운임","src":"상법 제853조 제1항 제8호"},{"t":"발행지와 그 발행연월일","src":"상법 제853조 제1항 제9호"},{"t":"수통의 선하증권을 발행한 때에는 그 수","src":"상법 제853조 제1항 제10호"},{"t":"운송인의 성명 또는 상호, 운송인의 주된 영업소 소재지. 운송인이 기명날인 또는 서명","src":"상법 제853조 제1항 제11호·제12호"},{"t":"선하증권번호는 법적 기재사항 목록에 없다","src":"기출 2026-22, 상법 제853조"},{"t":"송하인은 운송물 종류·중량 등 제2호 기재사항이 정확함을 운송인에게 담보한 것으로 본다","src":"상법 제853조 제3항"}]},{"머리":"운송인의 책임(상법 해상편)","줄":[{"t":"감항능력 주의의무: 운송인은 발항 당시 선박이 안전하게 항해할 수 있게 할 것, 필요한 선원 승선·선박의장·필요품 보급, 선창·냉장실 등 운송물 적재 부분을 적합한 상태에 둘 것에 주의를 다해야 한다. 주의를 다했음은 운송인이 증명","src":"상법 제794조"},{"t":"운송물에 관한 주의의무: 수령·선적·적부·운송·보관·양륙과 인도에 관한 주의의무","src":"상법 제795조 제1항"},{"t":"항해과실 면책: 선장·해원·도선사 등의 항해 또는 선박관리 행위나 화재로 생긴 손해는 면책. 운송인의 고의·과실로 인한 화재는 예외","src":"상법 제795조 제2항"},{"t":"면책사유: 해상위험, 불가항력, 전쟁·폭동·내란, 해적행위, 공권에 의한 제한, 송하인 또는 소유자 측 행위, 쟁의행위, 해상 인명·재산 구조행위와 정당한 항로이탈, 포장 불충분·기호 표시 불완전, 운송물의 특수한 성질·숨은 하자, 선박의 숨은 하자","src":"상법 제796조"},{"t":"책임한도: 매 포장 또는 선적단위당 666.67 계산단위와 중량 1kg당 2 계산단위 중 큰 금액. 운송인의 고의 또는 손해 발생 염려를 인식한 무모한 행위는 한도 제한 불가","src":"상법 제797조 제1항"},{"t":"컨테이너 등 통합용기 내 포장·선적단위 수를 선하증권에 기재하면 기재한 각 단위를 하나의 포장·선적단위로 본다. 기재하지 않으면 용기 내 전부가 하나의 단위","src":"상법 제797조 제2항 제1호"},{"t":"송하인이 운송물의 종류와 가액을 알리고 증권에 기재한 경우에는 책임한도 규정을 적용하지 않는다. 고의로 현저하게 부실 고지하면 운송인은 책임을 면한다","src":"상법 제797조 제3항"},{"t":"운송인의 손해배상 기본원칙은 과실책임주의. 감항능력 주의의무는 선적항 출항(발항) 당시에 부담","src":"기출 2026-27, 상법 제794조"},{"t":"운송물 주의의무: 선적, 적부, 적입, 보관, 하역 등 작업 때 화물을 주의 깊게 취급","src":"기출 2026-27"}]},{"머리":"면책약관(B/L 약관)","줄":[{"t":"이로약관(Deviation Clause): 항해 중 인명·재산 구조 등 상당한 이유로 예정항로 밖으로 항해해 생긴 손실에 운송인 면책","src":"기출 2022-23, 상법 제796조 제8호"},{"t":"부지약관(Unknown Clause): 컨테이너 내 화물은 화주 책임 아래 있으며 그 손실에 운송인 면책","src":"기출 2022-23"},{"t":"과실약관(Negligence Clause): 과실은 항해과실과 상업과실로 나눈다. 항해과실은 면책, 상업과실은 면책을 주장하지 못한다","src":"기출 2022-23, 상법 제795조 제2항"},{"t":"고가품약관(Valuable Cargo Clause): 송화인이 종가율에 따른 운임을 내지 않고 선적했으면 운송인은 일정 금액 한도 내에서 책임","src":"기출 2022-23"},{"t":"잠재하자약관(Latent Defect Clause): 선박의 잠재적(숨은) 하자로 생긴 손실에 운송인 면책. 화물 고유의 성질로 생긴 손실을 면책하는 것은 별개의 면책","src":"기출 2022-23, 상법 제796조 제10호·제11호"}]},{"머리":"선박 보안(ISPS Code)","줄":[{"t":"선박·여객(선원)·화물·항만시설 안전을 해치는 행위를 막기 위해 정부와 선사가 해야 할 의무를 규정","src":"기출 2026-28"},{"t":"선박은 보안계획서 승인과 보안심사를 받은 뒤 국제선박보안증서를 소지하고 운항","src":"기출 2026-28"},{"t":"항만은 보안평가를 실시하고 보안계획을 수립·시행해야 한다","src":"기출 2026-28"},{"t":"IMO가 주도했고 제정 당시 미국의 해운 보안법을 기반으로 삼았다","src":"기출 2026-28"},{"t":"대상 선박: 국제항해 여객선, 총톤수 500톤 이상 화물선, 이동식 해상 구조물(총톤수 300톤 이상이라는 문항 서술은 오답)","src":"기출 2026-28, 보충"}]}],"함정":[{"x":"잠재하자약관: 화물의 고유한 성질에 의하여 발생하는 손실에 대해 운송인은 면책이다.","o":"잠재하자약관은 선박의 숨은 하자에 관한 면책. 화물의 특수한 성질은 별개의 면책사유.","src":"기출 2022-23, 상법 제796조"},{"x":"적색 선하증권(Red B/L): 2가지 이상의 운송수단이 결합되어 국제복합운송이 발생하였음을 증명하는 선하증권이다.","o":"복합운송 증명은 Through B/L이다. Red B/L은 보험 기능이 결합된 증권(보충).","src":"기출 2024-8, 보충"},{"x":"컨테이너에 적재된 화물의 수량 단위를 명시하고 있는 경우, 그 명시 기준으로 손해배상을 한다.","o":"검수 필요. 상법 제797조 제2항은 기재한 단위를 책임한도 계산의 포장 단위로 본다고 정한다. 출제 문장의 정오는 원문 대조 필요.","src":"기출 2026-27, 상법 제797조"},{"x":"대상 선박은 국제항해취항 여객선, 총톤수 300톤 이상의 화물선 및 이동식 해상 구조물이다.","o":"화물선은 총톤수 500톤 이상(보충).","src":"기출 2026-28, 보충"}]},"#10":{"묶음":[{"머리":"항공기 종류와 용어","줄":[{"t":"High Capacity Aircraft(대형 기종): 데크(deck)로 상부실과 하부실이 나뉘고, 하부실에는 ULD 탑재가 가능하다","src":"기출 2021-28"},{"t":"여객기는 상부 공간을 객실, 하부 공간을 화물실로 쓴다. 대형 비행기 동체 하부 화물실에 싣는 화물이 Belly Cargo","src":"기출 2021-28, 2024-12"},{"t":"Convertible Aircraft: 화물실과 여객실을 상호 전용할 수 있게 제작된 항공기","src":"기출 2021-28"},{"t":"항공기는 국제민간항공조약에 의해 등록된 국가의 국적을 가진다","src":"기출 2021-28"},{"t":"블랙박스: 비행정보기록장치와 음성기록장치를 합쳐 부르는 이름","src":"기출 2021-28"},{"t":"Cabotage: 외국 항공기가 자국 내 일정 지점 간을 운행하는 것을 금지","src":"기출 2024-12"},{"t":"Pivot Weight: 각 ULD에 정해진 정액 한계중량","src":"기출 2024-12"},{"t":"Apron: 공항에서 승하기·화물 탑재 및 하역·정비·보급 등을 위해 항공기가 대기하는 장소","src":"기출 2024-12"},{"t":"Clearing House는 통관이 끝난 수출입화물이 대기하는 보관 장소가 아니다(문항의 오답 설명). 항공사 간 운임 정산을 맡는 기구","src":"기출 2024-12, 보충"}]},{"머리":"탑재방식과 ULD","줄":[{"t":"Bulk Loading: 좁은 화물실·한정된 공간에 탑재할 때 효율을 높일 수 있다. 안정성·기계화 면에서 가장 효율적인 방식은 아니다","src":"기출 2021-10"},{"t":"Pallet Loading: 지상 체류시간 단축에 기여. 파렛트를 굴림대 위로 굴려 기내 정위치에 고정","src":"기출 2021-10"},{"t":"Container Loading: 화물실에 맞는 항공화물 전용 용기를 사용","src":"기출 2021-10"},{"t":"ULD(단위탑재용기): 지상 조업시간 단축, 냉장·냉동 등 특수화물 운송 용이. 전기종 간 호환성이 높다고 하기 어렵고, 사용한 ULD를 전량 회수하는 것도 아니다","src":"기출 2022-26"}]},{"머리":"국제 항공기구와 협약","줄":[{"t":"ICAO(국제민간항공기구): 시카고 조약에 따라 국제항공의 안전성 확보와 항공질서 감시를 위한 관리기구. 각국 정부가 참여하는 국제협력기구","src":"기출 2024-18, 2026-29"},{"t":"IATA(국제항공운송협회): 민간항공사들이 협력해 안전하고 경제적인 항공운송업 발전과 항공교역 육성, 운송상 문제 해결. 표준운송약관·항공화물운송장·판매대리점 표준계약의 표준방식 설정, 여객운임·화물요율 협의 결정","src":"기출 2024-18"},{"t":"FIATA(국제운송주선인협회연합회), TIACA(국제항공화물협회)는 별도 기구","src":"기출 2024-18"},{"t":"항공운송 관련 국제규범: Warsaw Convention(바르샤바 협약), Montreal Agreement. CIM은 철도, CMR은 도로 운송 규범","src":"기출 2026-21, 보충"}]},{"머리":"항공화물 운임 요율","줄":[{"t":"GCR(일반화물요율): 모든 항공화물 요금 산정의 기본. 특정품목할인요율이나 품목분류요율을 적용받지 않는 모든 화물에 적용. 최저운임(M), 기본요율(N), 중량단계별 할인요율(Q)로 구성","src":"기출 2021-29, 2023-26"},{"t":"SCR(특정품목할인요율): 특정 품목에 대해 운송구간과 최저중량을 지정해 적용하는 할인운임","src":"기출 2023-26"},{"t":"CCR(품목분류요율): 특정 품목에 적용하는 할인 또는 할증 요율","src":"기출 2023-26"},{"t":"적용 우선순위: SCR·CCR이 우선하고, GCR은 이들이 적용되지 않을 때 적용","src":"기출 2023-26, 보충"},{"t":"BUC(Bulk Unitization Charge): 단위탑재용기별 한계중량을 기준으로 요금을 사전에 정해 판매. 용기 형태별 최저요금·최저중량을 정하고, 이를 초과하는 분량에 최저중량 초과요율을 부과","src":"기출 2026-7, 2021-29"},{"t":"종가운임(Valuation Charge): 가치가 높은 화물에 중량·용적이 아니라 가격을 기준으로 산정","src":"기출 2025-35, 2026-7"},{"t":"Chargeable Weight(운임부과중량): 실제 중량으로 계산한 운임과 부피(용적)로 계산한 운임을 비교해 운송인에게 유리한 쪽을 적용","src":"기출 2024-15"}]},{"머리":"항공운임 계산 순서","줄":[{"t":"용적중량(kg) = 가로 × 세로 × 높이(cm) ÷ 6,000. 실제 중량과 용적중량 중 큰 쪽을 운임부과중량으로 한다","src":"기출 2024-27, 2026-37"},{"t":"운임 = 부과중량 × 적용 요율(중량단계 구간 확인). 계산값이 최저요율보다 낮으면 최저요율 적용","src":"기출 2024-27, 2026-37"},{"t":"계산 예: 30kg, 40×50×60cm이면 용적중량 20kg. 큰 쪽 30kg × 9,000원 = 270,000원(최저요율 100,000원보다 큼)","src":"기출 2024-27"},{"t":"계산 예: 60kg, 80×80×36cm이면 용적중량 38.4kg. 실제 60kg이 크고 45kg 이상 구간 요율 9,000원 × 60 = 540,000원","src":"기출 2026-37"}]},{"머리":"항공운임 적용 규칙","줄":[{"t":"운임은 출발지 중량(kg 또는 lb)에 적용요율을 곱해 결정","src":"기출 2022-25"},{"t":"별도 규정이 없으면 요율과 요금은 가장 낮은 것을 적용","src":"기출 2022-25"},{"t":"운임과 종가 요금은 선불이거나 도착지 지불","src":"기출 2022-25"},{"t":"요율은 출발지 국가의 현지통화로 설정하며 출발지에서 목적지까지 한 방향으로 적용","src":"기출 2022-25, 2025-33"},{"t":"운임 산출의 근거 경로가 실제 운송경로와 일치해야 하는 것은 아니다","src":"기출 2022-25, 2025-33"},{"t":"요율 설정은 공항에서 공항까지이고 부수 서비스 요금은 별도 계산한다","src":"기출 2025-33"}]},{"머리":"항공운송장(AWB)","줄":[{"t":"송하인과 항공사의 운송계약 체결을 증명하는 서류. 유가증권이 아닌 단순 화물운송장 기능","src":"기출 2024-13, 2026-26"},{"t":"화물 접수를 증명하는 영수증에 불과하며 유통이 불가능하다. 지시식이 아니다","src":"기출 2024-13, 2026-26"},{"t":"통관 시 항공운임·보험료 증명자료로 세관신고서 기능, 수출입신고서 및 통관자료","src":"기출 2024-13, 2026-26"},{"t":"운임 및 요금 계산서 역할, 화물수령증 역할, 운송계약서 역할","src":"기출 2026-26"},{"t":"항공사가 발행하는 Master AWB과 혼재업자가 개별화주에게 발행하는 House AWB로 구분","src":"기출 2024-13"},{"t":"수하인은 기명식이 원칙이며, 화물 인수 후 발행된다(탑재 완료 이후에야 발행되는 것이 아니다)","src":"기출 2024-13, 보충"}]},{"머리":"수입화물 항공운송 취급 절차","줄":[{"t":"순서: 전문접수 및 항공기 도착 → 서류 분류 및 검토 → 창고분류 및 배정 → 화물분류 작업 → 도착 통지 → 운송장 인도 → 보세운송","src":"기출 2023-25"}]},{"머리":"항공화물운송주선업자(포워더)","줄":[{"t":"화주의 운송대리인이자 전문 혼재업자. 다양한 화주의 화물을 집하·혼재해 항공사에 운송 의뢰","src":"기출 2022-28, 2026-8"},{"t":"House Air Waybill로 송화인과 운송계약 체결. 자체 운송약관을 보유","src":"기출 2022-28, 2026-8"},{"t":"수출입 통관·보험에 관한 화주의 대리인. 벌크화물을 파렛트·컨테이너화하는 화물 단위화 기능","src":"기출 2022-28, 2026-8"},{"t":"Master Air Waybill을 발행하는 것은 항공사. 주선업자는 CFS(Container Freight Station)업자가 아니다","src":"기출 2022-28, 2026-8"}]}],"함정":[{"x":"High Capacity Aircraft는 소형기종의 항공기로서 데크(deck)에 의해 상부실 및 하부실로 구분되며 하부실은 구조상 ULD의 탑재가 불가능하다.","o":"대형 기종이며 하부실에 ULD 탑재가 가능하다.","src":"기출 2021-28"},{"x":"Bulk Loading은 안정성과 하역작업의 기계화 측면에서 가장 효율적인 방식이다.","o":"안정성·기계화 측면에서 효율적인 것은 Container/Pallet Loading 쪽. Bulk는 좁은 공간 활용에 유리.","src":"기출 2021-10"},{"x":"화물의 실제 운송 경로는 운임 산출시 근거 경로와 일치하여야만 한다.","o":"일치하지 않아도 된다.","src":"기출 2022-25, 2025-33"},{"x":"일반화물요율은 특정품목할인요율이나 품목별분류요율보다 우선하여 적용된다.","o":"SCR·CCR이 우선하고 GCR은 그 외 화물에 적용.","src":"기출 2023-26"},{"x":"수하인은 무기명식이 원칙이며, 항공기에 화물 탑재가 완료된 이후에 발행된다.","o":"출제 오답(바른 수치 미확인). 항공운송장은 기명식, 비유통성.","src":"기출 2024-13, 보충"},{"x":"항공운임은 ICAO의 기준에 따르며 요금, 요율 및 그와 관련된 규정은 운송장 발행이후 일주일의 기한을 두어 소급 적용한다.","o":"출제 오답(바른 수치 미확인). 운임 기준은 IATA 중심.","src":"기출 2025-33, 보충"},{"x":"화물요율의 설정은 공항에서 공항까지이며 부수적인 서비스 요금은 별도로 계산하지 않는다.","o":"부수 서비스 요금은 별도로 계산한다.","src":"기출 2025-33"},{"x":"모든 화물의 요율은 출발지 국가와 상관없이 kg당 요율로 설정한다.","o":"출발지 국가 기준 현지통화로 설정하며 kg 또는 lb당.","src":"기출 2025-33, 2022-25"},{"x":"송화인과 운송계약을 체결하고 Master Air Waybill을 발행한다. (포워더)","o":"Master AWB은 항공사 발행. 포워더는 House AWB.","src":"기출 2026-8"},{"x":"지시식으로 발행되어 매매가 가능한 유가증권으로 사용된다. (AWB)","o":"AWB은 비유통성의 화물운송장.","src":"기출 2026-26"},{"x":"Clearing House: 통관이 완료된 수출입화물이 일시 대기하는 보관 장소 (항공 용어 문항의 오답)","o":"설명이 틀린 용어. 정산기구로 알려져 있다(보충).","src":"기출 2024-12, 보충"},{"x":"CFS(Container Freight Station)업자이다. (항공화물운송주선업자 문항의 오답 선지)","o":"항공화물운송주선업자는 CFS업자가 아니다.","src":"기출 2022-28"},{"x":"운임 산출 시 근거가 되었던 경로는 화물의 실제 운송경로와 반드시 일치하여야 한다.","o":"일치하지 않아도 된다.","src":"기출 2025-33"}]},"#11":{"묶음":[{"머리":"복합운송 유형(조합)","줄":[{"t":"Piggy Back System: 철도운송 + 화물자동차운송","src":"기출 2024-6"},{"t":"Birdy Back System: 항공운송 + 화물자동차운송","src":"기출 2024-6"},{"t":"Fishy Back System: 해상운송 + 화물자동차운송","src":"기출 2024-6, 보충"},{"t":"Train & Ship System: 철도운송 + 해상운송","src":"기출 2024-6"},{"t":"Sea & Air System: 해상운송 + 항공운송","src":"기출 2024-6"}]},{"머리":"대륙횡단 서비스(Land Bridge)","줄":[{"t":"IPI(Interior Point Intermodal): 아시아 극동 화물을 북미 서부연안 항만까지 해상운송하고 철도·트럭으로 북미 내륙까지 복합운송","src":"기출 2024-14"},{"t":"RIPI(Reversed Interior Point Intermodal): 극동 화물을 파나마 운하를 거쳐 북미 동부연안 항만까지 해상운송하고 철도·트럭으로 내륙까지 운송","src":"기출 2022-18"},{"t":"ALB(American Land Bridge), MLB(Mini Land Bridge), CLB(Canadian Land Bridge)도 같은 유형의 선지","src":"기출 2022-18, 2024-14"}]},{"머리":"혼재서비스(Consolidation)","줄":[{"t":"혼재운송: 소량 컨테이너화물(LCL)을 컨테이너 단위 화물로 만들어 운송. 소량화물의 선적이 쉽고 비용 절감, 물량 단위화로 취급 용이","src":"기출 2023-30"},{"t":"Forwarder's Consolidation: 다수 송화인의 LCL 화물을 수출지 CFS에서 혼재해 FCL로 선적·운송하고, 수입지 CFS에서 분류해 다수 수화인에게 인도. 상대국의 파트너·대리점을 통한다. 주 수입원은 혼재 운임차액","src":"기출 2021-26, 2024-7, 2025-24"},{"t":"Buyer's Consolidation: 다수 송화인(수출자)의 화물을 혼재해 한 사람의 수화인(수입자)에게 운송","src":"기출 2023-30, 2025-24"},{"t":"Shipper's Consolidation: 단일 송화인이 여러 수화인의 화물을 모아 FCL로 만들어 운송하는 형태","src":"보충"},{"t":"혼재운송에서 운송주선인은 선박회사가 제공하지 않는 문전운송 서비스를 제공","src":"기출 2023-30"}]},{"머리":"국제물류주선업자(Freight Forwarder)·NVOCC","줄":[{"t":"주선업자의 기능: 화물의 집화·분배·혼재, 운송계약 체결, 선하증권 등 운송서류 작성, 운송수단·화물 포장형태·목적지 운송규칙에 대한 조언, 통관 대행","src":"기출 2022-27, 2023-27, 2024-4, 2025-22, 2025-23"},{"t":"수출화물을 본선에 인도하고 수입화물을 본선에서 인수한다. 화물 포장 및 보관 업무를 수행한다","src":"기출 2022-27, 2023-27"},{"t":"운송주체로서 자기 명의로 운송계약을 체결하고 자기 명의로 운송서류를 발행한다. 운송의 통제인 및 배송인","src":"기출 2022-27, 2023-27, 2024-4"},{"t":"복합운송에서 전체 운송 구간의 운송책임을 부담한다. 화주를 대신해 운송인과 운송계약을 체결","src":"기출 2025-23"},{"t":"주선업자는 혼재운송을 하며 LCL 화물도 취급한다","src":"기출 2025-23"},{"t":"화물인도지시서(D/O)를 작성해 선사에 제출하는 것은 주선업자의 기능이 아니다. 선박의 감항능력 유지와 컨테이너 야드 보안관리도 아니다","src":"기출 2023-27, 2024-4, 2025-22"},{"t":"NVOCC: 1984년 미국 신해운법으로 법적 지위를 인정받았다. 선박을 직접 보유하지 않는다","src":"기출 2024-40"},{"t":"NVOCC는 선박운송인(VOCC)에 대해서는 화주 입장에서, 화주에 대해서는 VOCC 입장에서 계약한다. 자기 명의로 B/L을 발행할 수 있다","src":"기출 2024-40"}]},{"머리":"컨테이너 종류","줄":[{"t":"Dry Container: 일반 건화물용","src":"기출 2022-15"},{"t":"Open Top Container: 지붕이 열린 형태","src":"기출 2022-15"},{"t":"Flat Rack Container: 목재·강재·승용차·기계류 등 중량화물용. 지붕과 벽을 없애고 4개 모서리에 기둥과 버팀대만 둬 전후·좌우·위쪽에서 적재·하역","src":"기출 2022-15"},{"t":"Live Stock Container: 동물용. Solid Bulk Container: 곡물·화학제품 등 건조 벌크용","src":"기출 2022-15"}]},{"머리":"위험물 컨테이너 수납 원칙","줄":[{"t":"컨테이너는 위험물을 수납하기 전에 충분히 청소·건조","src":"기출 2022-14"},{"t":"위험물의 이동·전도·충격·마찰·압력손상으로 위험이 생기지 않게 수납","src":"기출 2022-14"},{"t":"위험물의 어느 부분도 외부로 돌출하지 않게 수납한 뒤 컨테이너 문을 닫는다","src":"기출 2022-14"},{"t":"위험물을 컨테이너 일부에만 수납할 때는 문 가까운 곳에 수납(문에서 먼 곳이 아니다)","src":"기출 2022-14, 보충"},{"t":"위험물 컨테이너 문의 잠금장치와 봉인은 비상시에 지체 없이 열 수 있는 구조","src":"기출 2022-14"}]},{"머리":"컨테이너 터미널 시설·장비","줄":[{"t":"Apron: 선박이 접안하는 부두 안벽에 접한 야드 일부로 바다에 가장 가깝다. 갠트리 크레인(Gantry Crane)이 설치되어 컨테이너 적재·양륙 작업","src":"기출 2021-34"},{"t":"Berth(선석), Marshalling Yard, CY(Container Yard), CFS(Container Freight Station)도 터미널 시설 선지","src":"기출 2021-34"},{"t":"컨테이너 취급 장비: Gantry crane, Transtainer, Straddle carrier, Reach stacker. Dolly는 해상용 컨테이너 취급 장비로 꼽히지 않는다","src":"기출 2021-5"}]}],"함정":[{"x":"Fishy Back System: 해상운송 + 파이프라인운송","o":"Fishy Back은 해상 + 화물자동차.","src":"기출 2024-6, 보충"},{"x":"Forwarder’s consolidation은 단일 송화인의 화물을 다수의 수화인에게 운송하는 형태이다.","o":"다수 송화인의 LCL 화물을 혼재해 다수 수화인에게 운송.","src":"기출 2023-30"},{"x":"위험물을 컨테이너 일부에만 수납하는 경우에는 위험물을 컨테이너 문에서 먼 곳에 수납해야 한다.","o":"문 가까운 곳에 수납.","src":"기출 2022-14, 보충"},{"x":"운송수단을 보유하고, 계약운송인으로서 운송책임이 없다.","o":"주선업자(NVOCC)는 운송수단을 보유하지 않고 계약운송인으로서 운송책임을 진다.","src":"기출 2022-27"},{"x":"화물인도지시서(D/O)를 작성하여 선사에게 제출한다. (주선업자)","o":"D/O 발행은 선사·선박대리점 쪽 업무.","src":"기출 2023-27, 2024-4"},{"x":"혼재운송을 하지 않고 단일 화주의 FCL 화물만을 취급하기 때문에 LCL 화물은 취급하지 않는다.","o":"혼재운송을 하며 LCL 화물도 취급.","src":"기출 2025-23"},{"x":"화주에게 NVOCC 자기명의로 B/L을 발행할 수 없다.","o":"자기명의로 B/L을 발행할 수 있다.","src":"기출 2024-40"}]},"#12":{"묶음":[{"머리":"최단경로 문제","줄":[{"t":"목적: 출발지에서 도착지까지 거리(시간·비용) 합이 가장 작은 경로 찾기","src":"기출 2021-36, 2024-24, 2025-25"},{"t":"풀이 순서(다익스트라): 출발점 거리 0으로 두기 → 출발점에서 연결된 노드의 누적거리 갱신 → 확정되지 않은 노드 중 누적거리가 가장 작은 노드 확정 → 그 노드를 거쳐 다음 노드 누적거리 갱신 → 도착점이 확정될 때까지 반복","src":"보충"},{"t":"최단경로 네트워크(출발지에서 모든 지점까지의 최단경로 묶음)의 총길이를 구하는 문항도 나왔다. 8개 배송지에 대해 180km","src":"기출 2022-32"},{"t":"기출 결과값: 2021년 공장→물류센터 24km, 2024년 S→F 10, 2025년 S→F 12km","src":"기출 2021-36, 2024-24, 2025-25"}]},{"머리":"순회(TSP)와 개별 왕복 비교","줄":[{"t":"TSP(외판원 문제): 차량이 배송센터를 출발해 모든 배송지를 한 번씩 돌고 되돌아오는 시간·거리를 최소화","src":"기출 2021-40, 2022-29"},{"t":"물류센터에서 배송지 1·2·3을 무순위로 모두 경유하고 복귀하는 최소 소요시간: 230분","src":"기출 2022-29"},{"t":"개별 왕복 거리 = 각 수요처까지 왕복거리의 합, 순회 거리 = 센터→수요처들→센터를 한 바퀴 도는 거리. 감소 거리는 둘의 차","src":"기출 2025-26"},{"t":"계산 예: 개별 왕복 2×(7+8+5)=40km, 순회 센터→S1→S2→S3→센터 7+2+3+5=17km, 감소 23km","src":"기출 2025-26"}]},{"머리":"최대유량 문제","줄":[{"t":"목적: 화살표 방향으로만 흐를 수 있고 링크마다 용량이 있는 네트워크에서 출발지(X, S)에서 도착지(Y, F)로 보낼 수 있는 최대량","src":"기출 2021-33, 2023-34, 2025-28, 2026-36"},{"t":"풀이 순서(증가경로): ① 용량이 남은 경로를 하나 찾는다 ② 그 경로 링크 중 최소 잔여용량만큼 흘린다 ③ 링크 잔여용량을 갱신한다 ④ 더 이상 경로가 없을 때까지 반복 ⑤ 흘린 총량이 최대유량","src":"보충"},{"t":"최대유량 = 최소 절단(cut) 용량. 도착지로 들어가는 링크 용량 합이 상한","src":"보충"},{"t":"기출 결과값: 2021년 19톤, 2023년 16톤, 2025년 구간 폐쇄 비교 문항 (ㄱ) 30 (ㄴ) 28, 2026년 현재 28이고 C→B 구간을 3 용량으로 개통하면 2 증가","src":"기출 2021-33, 2023-34, 2025-28, 2026-36"},{"t":"링크를 새로 열거나 폐쇄하면 병목(최소 절단)이 바뀌는지 확인한다. 병목이 아닌 링크의 변경은 최대유량을 바꾸지 못한다","src":"기출 2025-28, 2026-36, 보충"}]},{"머리":"최소신장트리(MST)","줄":[{"t":"목적: 모든 노드(물류센터)를 연결하되 도로 총길이를 최소화. 간선 수는 노드 수 − 1","src":"기출 2022-31, 2026-38"},{"t":"풀이 순서(크루스칼): 간선을 짧은 순으로 정렬 → 가장 짧은 간선부터 고르되 사이클을 만들면 건너뜀 → 노드 수 − 1개를 고를 때까지 반복 → 선택한 간선 길이의 합","src":"보충"},{"t":"기출 결과값: 8곳 연결 최소 길이 23km, 9곳 연결 최소 길이 17km","src":"기출 2022-31, 2026-38"}]},{"머리":"절감(Saving)법과 경로 편성","줄":[{"t":"모든 방문처를 경유하는 차량 수를 최소로 하면서 차량 총 수송거리를 최소화하는 데 유용","src":"기출 2023-35"},{"t":"절감거리 = a + b − c (a, b는 배송센터에서 두 수요지까지 거리, c는 두 수요지 간 거리)","src":"기출 2023-35"},{"t":"절감거리가 큰 순위부터 차량 운행경로를 편성하고, 차량 적재용량 등 제약을 함께 고려","src":"기출 2023-35"},{"t":"배차되는 각 트럭의 용량은 특정 고객의 수요 이상이어야 한다","src":"기출 2023-35, 보충"},{"t":"스위핑법(Sweeping Method): 차고지에서 복수의 배송처로 선을 이은 뒤 시계·반시계 방향으로 돌려가며 순차 배송","src":"기출 2021-40"}]}],"함정":[{"x":"배차되는 각 트럭의 용량의 합은 총수요 이상이고 특정 고객의 수요보다는 작아야 한다.","o":"각 트럭 용량은 특정 고객의 수요 이상이어야 한다.","src":"기출 2023-35, 보충"}]},"#13":{"묶음":[{"머리":"수배송시스템 설계 원칙","줄":[{"t":"화물의 리드타임을 고려해 설계","src":"기출 2021-23, 2024-19, 2026-40"},{"t":"화물차의 적재율을 높일 수 있게 설계. 차량 회전율도 높인다","src":"기출 2021-23, 2023-37, 2025-27, 2026-40"},{"t":"편도수송·중복수송을 피한다","src":"기출 2021-23, 2025-27"},{"t":"동일 지역의 집화와 배송은 동시에(함께) 수행하도록 설계해 효율을 높인다","src":"기출 2021-23, 2025-27"},{"t":"배송경로는 가능한 서로 교차하지 않게 설계","src":"기출 2023-37, 2025-27, 2026-40"},{"t":"차량 운행대수·수배송비용·수배송 비율을 고려. 최단 운송루트를 개발하고 최적 운송수단을 선택. 운송 정보시스템을 활용","src":"기출 2023-37, 2024-19, 2025-27"},{"t":"설계 시 고려대상이 아닌 것: 선하증권(B/L)","src":"기출 2024-19"},{"t":"효율적인 수송경로를 위해 소형 차량을 우선 배차한다는 원칙은 없다","src":"기출 2026-40"}]},{"머리":"배송 방식","줄":[{"t":"단일배송: 하나의 배송처에 1대의 차량을 배차. 주문자가 신속한 배송을 요구할 때 이용","src":"기출 2021-39"},{"t":"루트(Route)배송: 일정한 배송경로를 반복적으로 배송. 비교적 광범위한 지역의 소량화물을 요구하는 다수 고객 대상","src":"기출 2021-39"},{"t":"변동 다이어그램(Diagram)배송: 배송처·배송물량 변화가 심할 때 방문 배송처, 방문순서, 방문시간 등을 매일 새롭게 설정. 배송에 관한 사항을 시간대별로 계획해 표로 작성하여 운행. 배송 관련 기준 설정이 중요","src":"기출 2021-39, 2023-16"},{"t":"고정 다이어그램배송: 배송처·물량이 일정해 정해진 시간표와 경로로 반복 운행하는 방식. 배송물량 기준으로 적합한 크기의 차량을 배차한다는 설명은 오답","src":"기출 2021-39, 보충"}]},{"머리":"수송계획 해법(수송표)","줄":[{"t":"북서코너법(North-West Corner Method): 수송표 좌측 상단(북서쪽)부터 우측 하단으로 수요량·공급량을 맞춰 차례로 할당. 신속하게 최초 실행가능 기저해를 구하지만 수송비용·거리·위치를 고려하지 못한다","src":"기출 2021-40, 2023-29"},{"t":"최소비용법(Least-Cost Method): 단위당 수송비용이 가장 낮은 칸에 우선 할당","src":"기출 2021-40, 2023-29"},{"t":"보겔추정법(VAM): 최선의 수송경로를 선택하지 못했을 때 추가로 생기는 기회비용을 고려해 할당","src":"기출 2021-40, 2023-29"},{"t":"보겔 풀이 순서: ① 각 행·열에서 가장 싼 비용과 둘째로 싼 비용의 차(기회비용)를 구한다 ② 그 차가 가장 큰 행 또는 열을 고른다 ③ 그 행·열에서 비용이 가장 낮은 칸에 가능한 최대량을 할당한다 ④ 공급·수요가 소진된 행·열을 지우고 반복","src":"보충"},{"t":"최소비용법 풀이 순서: ① 표 전체에서 단위비용이 가장 작은 칸을 찾는다 ② 가능한 최대량(공급과 수요 중 작은 쪽)을 할당 ③ 소진된 행·열을 지우고 다음으로 싼 칸 반복 ④ 총비용 = Σ(할당량 × 단위비용)","src":"기출 2022-33, 보충"},{"t":"수요보다 공급이 모자라 남는 미충족 수요에는 톤당 패널티를 곱해 총비용에 더한다","src":"기출 2022-33"},{"t":"초기해의 최적해 검사 기법: 디딤돌법(Stepping Stone Method). 도해법, 트리라벨링법, 의사결정수모형, 후방귀납법은 해당하지 않는다","src":"기출 2022-30"},{"t":"기출 결과값: 2022년 최소비용법 총비용(운송비+패널티) 12,210,000원, 2023년 보겔 적용 총운송비용 6,000,000원이며 공급지 B→수요지 X 운송량 400톤","src":"기출 2022-33, 2023-28"},{"t":"수송문제 정식화: 목적함수 최소화 Σ(단위비용 × 수송량), 제약식 — 공급지별 수송량 합은 공급량 이하(또는 같음), 수요지별 수송량 합은 수요량 이상(또는 같음), 수송량은 0 이상","src":"기출 2025-21, 보충"}]},{"머리":"수송수요 예측 모형","줄":[{"t":"중력모형: 지역 간 운송량은 경제규모에 비례하고 거리에 반비례한다는 가정의 화물분포모형. 단일제약모형, 이중제약모형이 있다","src":"기출 2021-37, 2023-31, 2025-30"},{"t":"회귀모형: 화물 수송량에 영향을 주는 변수 간 상관관계를 회귀식으로 도출해 장래 화물량을 예측","src":"기출 2023-31"},{"t":"성장인자모형: 물동량 배분패턴이 장래에도 일정하게 유지된다는 가정 아래 지역 간 물동량을 예측하는 화물분포모형","src":"기출 2023-31"},{"t":"엔트로피 극대화모형: 제약조건 아래 지역 간 물동량의 공간적 분산 정도가 극대화된다는 가정의 화물분포모형","src":"기출 2023-31"},{"t":"통행교차모형: 화물 발생량·도착량에 영향을 주는 변수 간 상관관계 식을 도출해 교차하는 화물량을 예측한다는 설명은 오답으로 출제. 교통량을 수단·교통망에 따라 시간·비용을 고려해 효율적으로 배분하는 설명도 오답","src":"기출 2021-37, 2023-31, 2025-30"},{"t":"화물분포모형에 해당하는 것: 성장인자법(성장률법). 로짓모형은 수단분담, 다이얼모형은 교통량 배분 쪽","src":"기출 2022-35, 보충"},{"t":"스위프(Sweep)모형은 경로 편성 기법이지 화물분포모형이 아니다","src":"기출 2025-30, 2021-40"}]},{"머리":"허브 앤 스포크(Hub & Spoke)","줄":[{"t":"집하한 화물을 하나의 대형 터미널(허브)에 모은 뒤 배송지별로 분류해 보내는 간선 운송 방식. 모든 노선이 허브를 중심으로 구축","src":"기출 2023-32, 2024-20, 2025-29, 2026-9"},{"t":"대규모 분류능력을 갖춘 허브터미널이 필요. 운송네트워크는 허브터미널과 집·배송센터로 구성","src":"기출 2023-32, 2024-20, 2026-9"},{"t":"운송노선이 단순해져 효율성이 높아지고 규모의 경제로 전체 효율이 오른다. 허브에 물량을 모아 적재율 향상","src":"기출 2023-32, 2024-20, 2025-29, 2026-9"},{"t":"단점: 근거리 물량도 허브를 거쳐 직송 대비 운송거리·시간이 늘어난다. 집배센터에 배달물량이 집중될 때 상하차 여건이 부족하면 배송 지연","src":"기출 2023-32, 2024-20, 2026-9"},{"t":"노선 수 계산: 허브 h개, 전체 터미널 n개이면 노선 = (n − h) + h(h − 1)/2. 16개 중 3개 허브는 13 + 3 = 16, 4개 허브는 12 + 6 = 18","src":"기출 2026-39, 보충"},{"t":"모든 터미널을 서로 직접 연결하면 n(n − 1)/2. 16개이면 120","src":"기출 2026-39, 보충"}]},{"머리":"Point to Point 방식","줄":[{"t":"하나의 터미널에서 다른 터미널로 보낼 화물을 각각의 터미널로 직접 발송","src":"기출 2024-32"},{"t":"여러 영업점을 순회하는 셔틀운송이 필요. 노선 수가 많고 분류작업 인건비가 늘 수 있다","src":"기출 2024-32"},{"t":"터미널 수가 많아 성수기 물량 증가에 대처가 양호","src":"기출 2024-32"}]}],"함정":[{"x":"셔틀노선의 증편이 용이하여 영업소 확대에 유리하다. (허브 앤 스포크)","o":"허브 앤 스포크의 특징이 아니다(Point to Point 쪽 설명).","src":"기출 2023-32, 2025-29"},{"x":"동일 지역에서 집화와 배송은 별개로 이루어지도록 설계한다.","o":"집화와 배송을 동시에 수행하도록 설계.","src":"기출 2021-23"},{"x":"배송경로는 상호 교차되도록 하여 운송루트에 다양성을 확보한다.","o":"배송경로는 교차하지 않게 설계.","src":"기출 2023-37, 2026-40"},{"x":"중복수송, 편도수송이 많이 일어나도록 설계하여 수송비용을 최소화한다.","o":"중복수송·편도수송을 피한다.","src":"기출 2025-27"},{"x":"성장인자모형은 확률이론을 기반으로 단기적 효과를 확인하기에 용이한 수단 분담모형이다.","o":"성장인자모형은 분배패턴이 일정하게 유지된다고 보는 화물분포모형.","src":"기출 2025-30"},{"x":"회귀모형은 일정구역에서 화물의 공간적 분산정도가 극대화한다는 가정에 기초한 비집계자료활용모형이다.","o":"분산정도 극대화는 엔트로피 극대화모형. 회귀모형은 변수 간 회귀식으로 예측.","src":"기출 2025-30, 2021-37"},{"x":"통행교차모형은 화물 발생량 및 도착량에 영향을 주는 다양한 변수 간의 상관관계에 대한 식을 도출하여 교차하는 화물량을 예측하는 화물분포모형이다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2025-30"},{"x":"스위프(Sweep)모형은 물동량 배분패턴이 장래에도 일정하게 유지된다는 가정 하에 지역 간의 물동량을 예측하는 화물분포모형이다.","o":"그 설명은 성장인자모형.","src":"기출 2025-30"},{"x":"통행교차모형: 교통량을 교통수단과 교통망에 따라 시간, 비용 등을 고려하여 효율적으로 배분하는 화물분포모형으로 로짓모형, 카테고리 분석모형 등이 있다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-31"},{"x":"북서코너법: 시간, 거리, 위치를 모두 고려하는 방법","o":"북서코너법은 수송비용·거리·위치를 고려하지 못한다.","src":"기출 2021-40"},{"x":"운송시스템을 구성하는 전체 노선 수가 증가하여 다양한 서비스의 제공이 가능하다. (허브 앤 스포크)","o":"노선이 단순해진다.","src":"기출 2026-9"},{"x":"복잡한 운송노선으로 인해 전체 운송비용 증가 / 운송네트워크의 복잡성으로 인해 전체 운송비용이 증가한다. (허브 앤 스포크 문항의 오답)","o":"노선이 단순해져 규모의 경제로 효율이 오른다.","src":"기출 2024-20, 2025-29, 2026-39"},{"x":"소형 차량을 우선 배차 / 배송경로 상호 교차 (수배송 설계 문항의 오답)","o":"ㄱ만 옳다(리드타임·적재율 고려).","src":"기출 2026-40"},{"x":"16개 터미널 중 4개를 허브터미널로 선택하여 운영할 경우, 총 20개의 왕복 노선이 필요하다.","o":"12 + 6 = 18개 노선.","src":"기출 2026-39"}]},"#14":{"묶음":[{"머리":"공동 수·배송","줄":[{"t":"장점: 동일지역·동일수하처에 대한 중복교차배송 배제, 물류관리 제반 경비의 규모의 경제, 적재율 향상, 물동량의 계절적 수요변동에 따른 차량운영 탄력성 확보","src":"기출 2024-21"},{"t":"기업의 영업기밀 유지가 쉬운 것은 공동 수·배송의 장점이 아니다. 오히려 어려워진다","src":"기출 2024-21"},{"t":"공동수배송 체계 구축·활성화는 운송 합리화 방안","src":"기출 2023-4, 2025-3, 2026-18"}]},{"머리":"화물운송정보시스템","줄":[{"t":"GIS-T(교통지리정보시스템): 디지털 지도에 각종 정보를 연결해 관리하고 분석·응용하는 시스템의 통칭. 교통정보를 관리·이용해 교통정책 수립 시 의사결정을 지원","src":"기출 2021-17"},{"t":"VMS(Vanning Management System, 적재관리시스템): 출하 화물의 양(중량·부피)에 따라 적정 크기의 차량을 고르고, 1대에 몇 개 배송처 화물을 실을지 계산하며, 화물 형상·중량에 따라 적재함 어느 부분에 실어야 효율적인지 시뮬레이션으로 알려준다","src":"기출 2021-17, 2023-12"},{"t":"TMS(Transportation Management System): 화물운송 때 따르는 자료와 정보를 신속히 수집해 효율적으로 관리. 수주 과정 입력 정보를 기초로 비용이 가장 적은 운송경로와 운송수단을 제공. 최적 운송계획과 차량 일정 관리. 고객의 다양한 요구를 수용하면서 수·배송비 절감","src":"기출 2024-37, 2026-14"},{"t":"WMS(창고관리시스템): 입고부터 출고까지 창고공간 효율의 최적화 등을 지원. 운송정보시스템(TMS)의 기능이 아니다","src":"기출 2026-14, 2023-12"},{"t":"그 밖의 선지: Port-MIS(항만운영정보시스템), TRS(주파수공용통신), RFID, Routing System, Tracking System, CVO(Commercial Vehicle Operating system), Cold Chain System, ITS(지능형교통시스템)","src":"기출 2021-17, 2023-12, 2024-37"}]}],"함정":[{"x":"화물이 입고되어 출고되기까지 창고공간 효율의 최적화 등을 지원한다. (TMS 설명 문항의 오답)","o":"창고공간 효율 지원은 WMS.","src":"기출 2026-14"},{"x":"기업의 영업기밀 유지가 용이 (공동 수·배송의 장점이 아닌 것)","o":"공동 수·배송은 영업기밀 유지가 어려워질 수 있다.","src":"기출 2024-21"}]},"#15":{"묶음":[{"머리":"운임 종류","줄":[{"t":"공적운임(Dead Freight): 운송계약을 운송수단 단위 또는 일정한 용기단위로 했을 때 실제로 적재능력만큼 운송하지 않아도 부담하는 미적재 운송량에 대한 운임. 부정기선 운임의 하나","src":"기출 2021-9, 2021-38"},{"t":"종가운임: 운송되는 화물의 가격(송장가액)에 따라 운임 수준이 달라지는 운임. 중량이 아니라 가격 기준","src":"기출 2023-14, 2024-33"},{"t":"최저운임: 운송량이 일정 수준 이하이거나 단거리 운송 등으로 실운임이 일정 수준 이하로 계산될 때 적용하는 최저 수준의 운임","src":"기출 2023-14"},{"t":"품목별운임: 운송 품목에 따라 요율을 달리하는 운임","src":"기출 2023-14"},{"t":"반송운임: 목적지 도착 후 인수 거부·인계 불능 등으로 반송 조치하고 받는 운임","src":"기출 2023-14"},{"t":"무차별운임: 운송거리, 서비스 수준, 운송량, 운송시간 등에 따라 차이가 생길 수 있어도 동일한 요율을 적용하는 운임","src":"기출 2023-14, 2021-9, 보충"},{"t":"거리체감운임: 운송거리가 길어질수록 km당 운임이 줄어드는 운임","src":"기출 2021-9, 2024-17, 보충"},{"t":"수요자(화주)가 인지하는 서비스 가치에 기초해 운임을 책정할 수 있다","src":"기출 2024-33"}]},{"머리":"운임 산정 기준과 영향 요인","줄":[{"t":"운임에 영향을 주는 요인: 화물의 중량, 부피, 운송 거리, 화물의 개수 모두","src":"기출 2021-16"},{"t":"운임 산정 기준: 중량기준, 용적기준, 종가기준, 개수기준, 표정기준","src":"기출 2022-9"},{"t":"용적기준: 양모·면화·코르크·목재·자동차 등 중량에 비해 부피가 큰 화물. Drum·Barrel·Roll처럼 화물 사이에 공간이 생기는 화물에도 적용. 손실공간을 감안해 적화계수 적용","src":"기출 2022-9, 2024-33"},{"t":"운송수단 선정 때 운송비용은 중요한 기준","src":"기출 2024-33"},{"t":"연료비, 수리비, 타이어비는 화물자동차 운송 비용 중 변동비","src":"기출 2024-33"}]},{"머리":"운송인의 책임(국내 육상·택배)","줄":[{"t":"운송사업자의 적재물사고(멸실·훼손·인도 지연) 손해배상 책임은 상법 제135조를 준용","src":"화물자동차 운수사업법 제7조 제1항"},{"t":"운송인은 자기·운송주선인·사용인 등이 운송물의 수령, 인도, 보관, 운송에 관해 주의를 게을리하지 않았음을 증명하지 못하면 멸실·훼손·연착 손해를 배상","src":"상법 제135조"},{"t":"전부멸실·연착 시 배상액은 인도할 날의 도착지 가격. 일부 멸실·훼손은 인도한 날의 도착지 가격. 운송인의 고의나 중대한 과실이면 모든 손해를 배상","src":"상법 제137조"},{"t":"수인이 순차로 운송하면 각 운송인은 연대하여 배상. 배상한 운송인은 원인을 만든 운송인에게 구상권. 원인 운송인을 모르면 운임액 비율로 분담","src":"상법 제138조"},{"t":"화물이 인도기한이 지난 후 3개월 이내에 인도되지 않으면 멸실된 것으로 본다","src":"화물자동차 운수사업법 제7조 제2항"}]}],"함정":[{"x":"무차별운임: 일정 운송량, 운송거리의 하한선 이하로 운송될 경우 일괄 적용되는 운임","o":"그 설명은 최저운임. 무차별운임은 조건과 관계없이 동일 요율을 적용.","src":"기출 2021-9, 2023-14"},{"x":"혼재운임: 단일화주의 화물을 운송수단의 적재능력만큼 적재 및 운송하고 적용 하는 운임","o":"출제 오답(바른 수치 미확인). 혼재는 여러 화주 화물을 섞어 싣는 것.","src":"기출 2021-9, 보충"},{"x":"전액운임: 운송거리에 비례하여 운임이 증가하는 형태의 운임","o":"출제 오답(바른 수치 미확인).","src":"기출 2021-9"},{"x":"거리체감운임: 운송되는 화물의 가격에 따라 운임의 수준이 달라지는 형태의 운임","o":"그 설명은 종가운임. 거리체감운임은 거리가 길수록 km당 운임이 줄어드는 운임.","src":"기출 2021-9, 보충"},{"x":"특별운임: 운송거리, 서비스 수준, 운송량, 운송시간 등에 따라 운임 차이가 발생 할 수 있음에도 불구하고 동일한 요율을 적용하는 형태의 운임","o":"그 설명은 무차별운임.","src":"기출 2023-14, 보충"}]},"#16":{"묶음":[{"머리":"택배 표준약관: 용어","줄":[{"t":"택배: 고객의 요청에 따라 운송물을 고객(송화인)의 주택·사무실 등에서 수탁해 고객(수화인)의 주택·사무실 등까지 운송해 인도하는 것","src":"기출 2023-38"},{"t":"운송장: 사업자와 고객(송화인) 간 택배계약의 성립과 내용을 증명하기 위해 사업자의 청구에 의해 고객(송화인)이 발행한 문서","src":"기출 2021-13, 2023-38"},{"t":"수탁: 사업자가 택배를 수행하기 위해 고객(송화인)으로부터 운송물을 수령하는 것","src":"기출 2021-13, 2023-38"},{"t":"인도: 사업자가 고객(수화인)에게 운송장에 기재된 운송물을 넘겨주는 것","src":"기출 2021-13, 2023-38"},{"t":"택배사업자: 택배를 영업으로 하며 상호가 운송장에 기재된 운송사업자","src":"기출 2021-13, 2023-38"},{"t":"손해배상한도액: 운송물의 멸실·훼손·연착 시 사업자가 손해를 배상할 수 있는 최고 한도액","src":"기출 2021-13"}]},{"머리":"운송장 기재와 교부","줄":[{"t":"고객(송화인)이 사업자에게 교부하는 사항: 송화인의 주소·이름(또는 상호)·전화번호, 수화인의 주소·이름(또는 상호)·전화번호, 운송물의 종류(품명)·수량·가액, 운송상의 특별한 주의사항","src":"기출 2021-11"},{"t":"사업자가 운송장에 기재하는 사항: 사업자의 상호·대표자명·주소·전화번호·담당자(집화자) 이름, 손해배상한도액, 운임 기타 운송에 관한 비용 및 지급방법, 운송물의 중량 및 용적 구분, 문의처 전화번호","src":"기출 2021-11, 2023-39, 2024-29"},{"t":"운송물의 원산지(제조지)는 운송장 교부사항이 아니다","src":"기출 2024-29"},{"t":"택배운송장의 역할: 송화인과 택배회사 간 계약서, 택배요금 영수증, 화물인수증, 화물취급지시서, 배달완료 증빙. 사업자등록증 역할은 없고 유통 가능한 유가증권도 아니다","src":"기출 2021-32, 2026-10"}]},{"머리":"수탁 거절 사유","줄":[{"t":"운송물 1포장의 가액이 300만원을 초과하는 경우(100만원 이하라서 거절하는 것이 아니다)","src":"기출 2021-18, 2025-39"},{"t":"화약류·인화물질 등 위험한 물건","src":"기출 2025-39"},{"t":"재생 불가능한 계약서·원고·서류 등","src":"기출 2025-39"},{"t":"살아 있는 동물, 동물사체 등","src":"기출 2021-18, 2025-39"},{"t":"현금·카드·어음·수표·유가증권 등 현금화가 가능한 물건","src":"기출 2025-39, 2022-37"},{"t":"운송물의 인도예정일(시)에 따른 운송이 불가능한 경우, 운송이 법령·사회질서·선량한 풍속에 반하는 경우, 고객(송화인)이 운송장에 필요한 사항을 기재하지 않은 경우","src":"기출 2021-18"},{"t":"취급이 금지되는 품목 예: 상품권, 복권, 신용카드, 현금. 유리제품은 금지 품목이 아니다","src":"기출 2022-37"}]},{"머리":"포장·운임·할증","줄":[{"t":"고객(송화인)은 운송물을 성질·중량·용량에 따라 운송에 적합하게 포장한다","src":"기출 2022-38, 2024-34"},{"t":"사업자는 운송물 포장이 운송에 적합하지 않으면 고객(송화인)의 승낙을 얻어 운송 중 생길 수 있는 충격량을 고려해 포장한다. 이때 추가 포장비용은 고객(송화인)이 부담","src":"기출 2022-38, 2024-34, 보충"},{"t":"사업자는 운송물을 수탁한 뒤 포장 외부에 운송물의 종류와 수량, 인도예정일(시), 운송상 특별한 주의사항을 표시","src":"기출 2022-38, 2024-34"},{"t":"운반 도중 포장이 훼손되어 재포장한 경우, 고객(송화인)에게 그 사실을 알려야 한다(인도한 뒤에 알리는 것이 아니다)","src":"기출 2022-38, 2024-34, 보충"},{"t":"운송물이 포장 당 50만원을 초과하거나 운송상 특별한 주의를 요하면 사업자는 별도 할증요금을 청구할 수 있다","src":"기출 2024-34, 2025-36"},{"t":"사업자는 운송물을 수탁할 때 고객(송화인)에게 운임을 청구할 수 있고, 합의에 따라 인도할 때 수화인에게 청구할 수도 있다. 수화인이 운임을 내지 않으면 운송물을 유치할 수 있다","src":"기출 2025-36"},{"t":"고객 사유로 운송물을 돌려보내거나 도착지 주소가 바뀌면 사업자는 추가 요금을 청구할 수 있다","src":"기출 2025-36"}]},{"머리":"사고증명서·인도예정일·책임 소멸","줄":[{"t":"사고증명서: 운송 중 멸실·훼손·연착에 대해 고객(송화인) 청구가 있으면 사고 발생일부터 1년에 한해 발행","src":"기출 2022-39, 보충"},{"t":"인도예정일 기재가 없는 경우: 수탁일부터 2일, 도서·산간지역은 3일째 날까지 인도","src":"기출 2022-39, 보충"},{"t":"일부 멸실·훼손에 대한 사업자 책임은 수화인이 운송물을 수령한 날부터 14일 이내에 통지를 발송하지 않으면 소멸","src":"기출 2022-39, 보충"},{"t":"일부 멸실·훼손·연착에 대한 책임은 수령한 날부터 1년이 지나면 소멸","src":"기출 2022-39, 보충"},{"t":"사업자가 일부 멸실·훼손 사실을 알면서 숨기고 인도한 경우 책임은 수령한 날부터 5년간 존속","src":"기출 2022-39"}]},{"머리":"손해배상","줄":[{"t":"사업자는 고객(송화인)이 손해입증서류를 제출한 날부터 30일 이내에 우선 배상","src":"기출 2022-40"},{"t":"고객이 운송장에 운송물 가액을 기재하지 않은 경우 손해배상한도액은 50만원. 할증요금을 낸 경우 각 운송가액 구간별 운송물의 최고가액","src":"기출 2026-15"},{"t":"전부 멸실: 인도예정일 인도예정장소 가액 기준 손해액 또는 입증한 손해액. 일부 멸실: 인도일 인도장소 가액 기준. 훼손: 수선 가능하면 실수선비용(A/S비용), 불가능하면 일부 멸실에 준함","src":"기출 2026-15"},{"t":"연착되고 멸실·훼손이 없으면 훼손 규정(제2항 제3호)을 준용. 연착되고 일부 멸실·훼손이면 해당 규정에 준하되 인도일을 인도예정일로 본다","src":"기출 2026-15"}]},{"머리":"인도할 수 없는 운송물의 처분","줄":[{"t":"사업자는 고객(송화인)에게 1개월 이상의 기간을 정해 그 기간 내 처분 지시가 없으면 경매한다는 뜻을 밝혀 처분 지시를 통지","src":"기출 2025-37"},{"t":"수화인이 수령을 거절하거나 수령 불능이면 먼저 수화인에게 1주일 이상의 기간을 정해 수령을 요청하고, 그 기간 내에도 수령하지 않으면 송화인에게 통지","src":"기출 2025-37"}]},{"머리":"택배 사업 특성","줄":[{"t":"door-to-door 소화물 배송. 사업허가를 받은 운송업자의 책임 아래 이루어지는 일관책임체계","src":"기출 2021-35, 2022-36"},{"t":"물류거점, 물류정보시스템, 운송네트워크가 필요한 산업. 전자상거래 확산에 따른 다빈도 배송 수요로 성장","src":"기출 2021-35, 2024-36"},{"t":"택배요금은 서비스 업체, 수화인 지역, 화물 규격·중량에 따라 다르다. 국가가 정한 동일 요금이 아니다","src":"기출 2021-35"},{"t":"이용자 측면 특징: 소형·소량화물 운송체계, 규격화된 포장서비스, 단일 운임·요금체계, 운송업자가 책임을 지는 일관책임체계","src":"기출 2022-36"},{"t":"택배사업은 집하·운송·중계에 많은 인력이 든다. 정보시스템 구축, 차량·터미널·분류기기 등 대규모 장비·시설 투자, 적정 수의 영업소 네트워크 설치가 필요","src":"기출 2024-36"},{"t":"위탁 영업소: 회사가 점포와 집배·배송 차량을 제공하고 수탁자가 운영하는 영업장","src":"기출 2023-36"},{"t":"택배물류 형태: C2B 택배 — 구매 제품의 A/S 화물과 구매취소 반품이 주를 이루고 판매자의 폐기물 회수를 포함. 전자상거래 증가로 늘 것으로 예상","src":"기출 2023-40"},{"t":"B2C, C2C, B2G, C2G도 택배물류 형태 선지로 나온다","src":"기출 2023-40"}]},{"머리":"생활물류서비스산업발전법","줄":[{"t":"택배서비스사업: 화물자동차 운수사업법 제3조 제1항에 따라 허가받은 화물자동차 운송사업용 화물자동차로 집화·분류 등을 거쳐 화물을 배송하는 사업","src":"생활물류서비스산업발전법 제2조 제3호 가목"},{"t":"택배서비스사업자: 화물자동차 운송사업 허가를 받은 뒤 제5조 제1항에 따라 택배서비스사업을 등록한 자","src":"생활물류서비스산업발전법 제2조 제4호 가목"},{"t":"택배서비스종사자: 택배서비스사업자 또는 영업점과 운송 위탁계약이나 근로계약 등으로 집화·배송에 종사하는 사람","src":"생활물류서비스산업발전법 제2조 제6호 가목"},{"t":"택배서비스사업 등록: 국토교통부장관에게 등록. 요건은 화물자동차 운송사업 허가, 시설·장비·영업점 등 대통령령 기준. 등록한 날부터 3년의 범위에서 등록요건을 신고","src":"생활물류서비스산업발전법 제5조"},{"t":"택배서비스 운송 위탁계약 해지: 60일 이상의 유예기간을 두고 위반 사실을 구체적으로 밝히며 시정하지 않으면 해지한다는 사실을 서면으로 2회 이상 통지. 계약을 지속하기 어려운 중대한 사유가 있으면 예외","src":"생활물류서비스산업발전법 제11조 제1항, 기출 2025-40"},{"t":"해지 절차를 거치지 않은 해지는 효력이 없다. 사업자 등록이 취소되면 위탁계약은 해지된 것으로 본다","src":"생활물류서비스산업발전법 제11조 제2항·제3항"},{"t":"계약 갱신: 종사자가 계약기간 만료 전 150일부터 60일 사이에 갱신을 요구하고 총 계약기간이 6년 이하이면 법정 사유 외에는 거절할 수 없다. 거절 시 요구받은 날부터 15일 이내 서면 통지","src":"생활물류서비스산업발전법 제10조 제1항·제3항"}]},{"머리":"영업장 구분","줄":[{"t":"터미널은 화물의 분류와 차량의 간선운행 기능을 가진 영업장","src":"기출 2023-36, 보충"},{"t":"취급점·특약점·대리점의 정의는 문항에서 서로 바꿔 놓은 형태로 출제되었다","src":"기출 2023-36"}]}],"함정":[{"x":"‘인도’라 함은 사업자가 고객(송화인)에게 운송장에 기재된 운송물을 넘겨주는 것을 말한다.","o":"인도는 사업자가 고객(수화인)에게 넘겨주는 것.","src":"기출 2021-13"},{"x":"‘수탁’이라 함은 사업자가 택배를 수행하기 위하여 고객(수화인)으로부터 운송물을 수령하는 것을 말한다.","o":"수탁은 고객(송화인)으로부터 수령하는 것.","src":"기출 2023-38"},{"x":"택배 서비스 제공업체, 수화인의 지역, 화물의 규격과 중량 등에 상관없이 국가에서 정한 동일한 요금이 적용된다.","o":"업체·지역·규격·중량에 따라 요금이 다르다.","src":"기출 2021-35"},{"x":"사업자는 운송 중에 발생한 운송물의 멸실, 훼손 또는 연착에 대하여 고객(송화인)의 청구가 있으면 그 발생일로부터 6개월에 한하여 사고증명서를 발행한다.","o":"1년(보충).","src":"기출 2022-39, 보충"},{"x":"사업자는 운송장에 운송물의 인도예정일의 기재가 없는 경우, 도서ㆍ산간지역은 운송물의 수탁일로부터 5일에 해당하는 날까지 인도한다.","o":"도서·산간은 수탁일로부터 3일(보충).","src":"기출 2022-39, 보충"},{"x":"운송물의 일부 멸실 또는 훼손에 대한 사업자의 손해배상책임은 고객(수화인)이 운송물을 수령한 날로부터 10일 이내에 그 사실을 사업자에게 통지를 발송하지 아니하면 소멸한다.","o":"14일 이내(보충).","src":"기출 2022-39, 보충"},{"x":"운송물의 일부 멸실, 훼손 또는 연착에 대한 사업자의 손해배상책임은 고객(수화인)이 운송물을 수령한 날로부터 6개월이 경과하면 소멸한다.","o":"1년이 경과하면 소멸(보충).","src":"기출 2022-39, 보충"},{"x":"사업자가 운반하는 도중에 운송물의 포장이 훼손되어 재포장을 한 경우, 운송물을 인도한 후 고객(송화인)에게 그 사실을 알려야 한다.","o":"출제 오답(바른 수치 미확인). 재포장 사실은 고객(송화인)에게 알려야 하며 인도 후에 알리는 것이 아니다(보충).","src":"기출 2024-34, 2022-38"},{"x":"고객(송화인, 수화인)의 사유로 운송물을 돌려보내거나 도착지 주소지가 변경되는 경우에 사업자는 따로 추가 요금을 청구할 수 없다.","o":"추가 요금을 청구할 수 있다.","src":"기출 2025-36"},{"x":"소품종 대량생산 체제로 전환되면서 운송단위가 대량화되고 있다. (택배)","o":"다품종 소량생산 쪽으로 가며 소량·다빈도.","src":"기출 2024-36"},{"x":"유통 가능한 유가증권 역할을 한다. (택배운송장)","o":"유가증권이 아니다.","src":"기출 2026-10"},{"x":"터미널은 회사가 점포를 개설하여 직접 운영하는 영업장을 말한다.","o":"출제 오답(바른 수치 미확인). 터미널은 분류·간선운행 기능을 하는 영업장.","src":"기출 2023-36"},{"x":"특약점은 일정한 지역의 영업거점으로 집배차량 통제 및 집배구역을 관리하고 주로 집배ㆍ배송업무를 수행하는 영업장을 말한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-36"},{"x":"대리점은 수탁자가 점포, 차량을 준비하여 화물집화만을 수행하는 영업장을 말한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-36"},{"x":"취급점은 화물의 분류, 차량의 간선운행 기능을 갖는 영업장을 말한다.","o":"그 설명은 터미널(보충).","src":"기출 2023-36, 보충"},{"x":"운송물 1포장의 가액이 100만원 이하인 경우 수탁을 거절할 수 있다.","o":"300만원을 초과하는 경우.","src":"기출 2021-18, 2025-39"},{"x":"공식적인 계약에 따른 개인 보증제도 (택배 이용자 측면 특징 문항의 오답 선지)","o":"택배는 일관책임체계이며 개인 보증제도가 특징이 아니다.","src":"기출 2022-36"},{"x":"사업자는 운송물의 포장이 운송에 적합하지 아니한 때 승낙을 얻어 포장한 경우 추가 포장비용은 사업자가 부담한다.","o":"고객(송화인)이 부담(보충).","src":"기출 2022-38, 보충"}]}};
